import{_ as r,o as a,c as n,ag as o}from"./chunks/framework.BJFNwp4n.js";const m=JSON.parse('{"title":"Module 6：巩固与个性化","description":"","frontmatter":{},"headers":[],"relativePath":"zh/more/maltese/modules/maltese-module6-analysis.md","filePath":"zh/more/maltese/modules/maltese-module6-analysis.md"}'),s={name:"zh/more/maltese/modules/maltese-module6-analysis.md"};function i(g,t,e,d,l,b){return a(),n("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1794416186000"},[...t[0]||(t[0]=[o('<h1 id="module-6-巩固与个性化" tabindex="-1">Module 6：巩固与个性化 <a class="header-anchor" href="#module-6-巩固与个性化" aria-label="Permalink to &quot;Module 6：巩固与个性化&quot;">​</a></h1><h2 id="封面" tabindex="-1">封面 <a class="header-anchor" href="#封面" aria-label="Permalink to &quot;封面&quot;">​</a></h2><table tabindex="0"><thead><tr><th>原文</th><th>中文与词语解析</th></tr></thead><tbody><tr><td>MQF 2 – Maltese Language and Cultural Orientation for Foreigners</td><td>马耳他资格框架第 2 级：面向外国人的马耳他语及文化入门。<br><strong>MQF 2</strong>：资格级别。<br><strong>Maltese Language</strong>：马耳他语。<br><strong>Cultural Orientation</strong>：文化导向／入门。<br><strong>for Foreigners</strong>：面向外国人。</td></tr><tr><td>Module 6 / Consolidation and Personalisation</td><td>第六模块：巩固与个性化。<br><strong>Module 6</strong>：第六模块。<br><strong>Consolidation</strong>：巩固所学。<br><strong>and</strong>：与。<br><strong>Personalisation</strong>：结合个人情况运用。原封面为英语，不把自拟马耳他语标题冒充原文。</td></tr></tbody></table><hr><h2 id="_1-七类口语主题与示范回答" tabindex="-1">1 七类口语主题与示范回答 <a class="header-anchor" href="#_1-七类口语主题与示范回答" aria-label="Permalink to &quot;1 七类口语主题与示范回答&quot;">​</a></h2><h3 id="七类口语题与时态" tabindex="-1">七类口语题与时态 <a class="header-anchor" href="#七类口语题与时态" aria-label="Permalink to &quot;七类口语题与时态&quot;">​</a></h3><p><code>It-Taħdit</code>＝口语。<code>B’liema temp se titkellem dwar dawn it-temi?</code>＝你将用哪种时态谈这些主题？</p><p><strong>B’liema</strong>：用哪一种。<br><strong>temp</strong>：这里是语法“时态”，不是天气。<br><strong>se titkellem</strong>：你将说话。<br><strong>dwar</strong>：关于。<br><strong>dawn it-temi</strong>：这些主题。<br><strong>Passat</strong>：过去时。<br><strong>Preżent</strong>：现在时。<br><strong>Futur</strong>：将来时。</p><table tabindex="0"><thead><tr><th>主题与全部提示</th><th>中文、词语和时态</th></tr></thead><tbody><tr><td>1. Jien: iddeskrivi lilek innifsek, xi tgħid dwarek u dwar ħajtek? X’edukazzjoni għandek? X’taħdem? (Xogħol) X’inhuma l-passatempi tiegħek?</td><td>自我介绍，以现在时为主，已完成教育可用过去时。<br><strong>Jien</strong>：我。<br><strong>iddeskrivi</strong>：描述。<br><strong>lilek innifsek</strong>：你自己。<br><strong>xi tgħid</strong>：你会说什么。<br><strong>dwarek</strong>：关于你。<br><strong>u dwar ħajtek</strong>：以及关于你的生活。<br><strong>X’edukazzjoni għandek</strong>：你有什么教育背景。<br><strong>X’taħdem / Xogħol</strong>：做什么工作／工作。<br><strong>X’inhuma</strong>：它们是什么。<br><strong>l-passatempi tiegħek</strong>：你的爱好。</td></tr><tr><td>2. Il-familja: min huma l-membri tal-familja tiegħek? X’jisimhom? Fejn jgħixu? Xi tgħid fuqhom?</td><td>家庭，通常现在时。<br><strong>Il-familja</strong>：家庭。<br><strong>min huma</strong>：他们是谁。<br><strong>l-membri</strong>：成员。<br><strong>tal-familja tiegħek</strong>：你的家庭的。<br><strong>X’jisimhom</strong>：他们叫什么，-hom＝他们。<br><strong>Fejn jgħixu</strong>：他们住哪里。<br><strong>Xi tgħid fuqhom</strong>：你会怎样介绍他们，fuqhom＝关于他们。</td></tr><tr><td>3. Il-pjanijiet: x’se tagħmel fil-futur? Qed tippjana xi safra? Xi avveniment speċjali? X’se jiġri?</td><td>计划：将来时，正在计划的行为可用 qed。<br><strong>Il-pjanijiet</strong>：计划，复数。<br><strong>x’se tagħmel</strong>：你将做什么。<br><strong>fil-futur</strong>：未来。<br><strong>Qed tippjana</strong>：你正在计划。<br><strong>xi safra</strong>：某次旅行。<br><strong>xi avveniment speċjali</strong>：某个特别活动。<br><strong>X’se jiġri</strong>：将发生什么。</td></tr><tr><td>4. L-ikel: liema hu l-ikel favorit tiegħek? Hemm xi ħaġa li żgur ma tikolx? Tħobb issajjar?</td><td>食物：习惯与偏好用现在时。<br><strong>L-ikel</strong>：食物。<br><strong>liema hu</strong>：哪一个是。<br><strong>l-ikel favorit tiegħek</strong>：你最喜欢的食物。<br><strong>Hemm xi ħaġa</strong>：有没有什么东西。<br><strong>li żgur ma tikolx</strong>：你肯定不吃的。<br><strong>Tħobb issajjar</strong>：你喜欢做饭吗。</td></tr><tr><td>5. Id-divertiment: kif tħobb tiddeverti? Fejn tmur u ma’ min?</td><td>娱乐：通常现在时。<br><strong>Id-divertiment</strong>：娱乐。<br><strong>kif tħobb tiddeverti</strong>：你喜欢怎样消遣。<br><strong>Fejn tmur</strong>：你去哪里。<br><strong>u ma’ min</strong>：和谁。</td></tr><tr><td>6. It-trasport: X’mezzi ta’ trasport tuża? Liema tippreferi? Liema jdejqek?</td><td>交通：日常习惯用现在时。<br><strong>It-trasport</strong>：交通。<br><strong>X’mezzi ta’ trasport</strong>：哪些交通方式。<br><strong>tuża</strong>：你使用。<br><strong>Liema tippreferi</strong>：你更喜欢哪一种。<br><strong>Liema jdejqek</strong>：哪一种令你不快，-ek＝你。</td></tr><tr><td>7. L-ivvjaġġar / is-safar: Tħobb issiefer? Liema pajjiżi ġieli żort? Liema l-iktar li għoġbok u għaliex? Hemm xi pajjiż li ma jogħġbokx? Iddeskrivi safra li għamilt.</td><td>旅行：偏好用现在时，经历用过去时。<br><strong>L-ivvjaġġar / is-safar</strong>：旅行。<br><strong>Tħobb issiefer</strong>：喜欢出国旅行吗。<br><strong>Liema pajjiżi</strong>：哪些国家。<br><strong>ġieli żort</strong>：你曾游览过。<br><strong>Liema l-iktar li għoġbok</strong>：哪一个最让你喜欢。<br><strong>u għaliex</strong>：为什么。<br><strong>Hemm xi pajjiż</strong>：有没有某个国家。<br><strong>li ma jogħġbokx</strong>：你不喜欢的。<br><strong>Iddeskrivi safra</strong>：描述一次旅行。<br><strong>li għamilt</strong>：你经历过的。</td></tr></tbody></table><h3 id="七类较完整示范回答及逐句分析" tabindex="-1">七类较完整示范回答及逐句分析 <a class="header-anchor" href="#七类较完整示范回答及逐句分析" aria-label="Permalink to &quot;七类较完整示范回答及逐句分析&quot;">​</a></h3><p>每组连续读即构成口语小段；人物 Alex 为虚构。男性形容词可按学习者情况改成阴性。</p><table tabindex="0"><thead><tr><th>主题与回答句</th><th>中文与逐词／短语解析</th></tr></thead><tbody><tr><td>1a. Jisimni Alex, għandi tletin sena u noqgħod l-Imsida ma’ ħabib tiegħi.</td><td>我叫 Alex，30 岁，和朋友住 Msida。<br><strong>Jisimni</strong>：我叫。<br><strong>Alex</strong>：虚构人名。<br><strong>għandi tletin sena</strong>：我三十岁。<br><strong>u noqgħod</strong>：并居住。<br><strong>l-Imsida</strong>：在 Msida。<br><strong>ma’ ħabib tiegħi</strong>：与我的朋友。</td></tr><tr><td>1b. Studjajt l-informatika u issa naħdem f’uffiċċju żgħir fil-Belt.</td><td>学过计算机，现在 Valletta 的小办公室工作。<br><strong>Studjajt</strong>：我学习过。<br><strong>l-informatika</strong>：计算机／信息学。<br><strong>u issa</strong>：而现在。<br><strong>naħdem</strong>：我工作。<br><strong>f’uffiċċju żgħir</strong>：在小办公室。<br><strong>fil-Belt</strong>：在 Valletta，首都的习惯称法。</td></tr><tr><td>1c. Fil-ħin liberu nħobb naqra, insajjar u nimxi ħdejn il-baħar biex nistrieħ.</td><td>空闲时喜欢阅读、做饭、海边散步休息。<br><strong>Fil-ħin liberu</strong>：空闲时。<br><strong>nħobb</strong>：我喜欢。<br><strong>naqra</strong>：读书。<br><strong>insajjar</strong>：做饭。<br><strong>u nimxi ħdejn il-baħar</strong>：并在海边走。<br><strong>biex nistrieħ</strong>：为了休息。</td></tr><tr><td>2a. Il-familja tiegħi tinkludi lil ommi Maria, missieri Paul u oħti Anna.</td><td>家人有母亲 Maria、父亲 Paul、姐妹 Anna。<br><strong>Il-familja tiegħi</strong>：我的家庭。<br><strong>tinkludi</strong>：包括。<br><strong>lil ommi Maria</strong>：我的母亲 Maria。<br><strong>missieri Paul</strong>：我的父亲 Paul。<br><strong>u oħti Anna</strong>：我的姐妹 Anna。</td></tr><tr><td>2b. Huma jgħixu barra minn Malta, iżda nitkellmu fuq it-telefon kważi kuljum.</td><td>他们住马耳他以外，但几乎每天通电话。<br><strong>Huma</strong>：他们。<br><strong>jgħixu</strong>：居住。<br><strong>barra minn Malta</strong>：马耳他之外。<br><strong>iżda</strong>：但是。<br><strong>nitkellmu</strong>：我们交谈。<br><strong>fuq it-telefon</strong>：通过电话。<br><strong>kważi kuljum</strong>：几乎每天。</td></tr><tr><td>2c. Ommi tħobb issajjar, missieri jħobb il-ġnien, u oħti għadha tistudja.</td><td>母亲爱做饭，父亲爱园艺，姐妹还在读书。<br><strong>Ommi tħobb issajjar</strong>：母亲喜欢做饭。<br><strong>missieri jħobb il-ġnien</strong>：父亲喜欢花园。<br><strong>u oħti</strong>：而我姐妹。<br><strong>għadha tistudja</strong>：仍在学习，-ha 表她。</td></tr><tr><td>3a. Fil-futur se nkompli nistudja l-Malti għax nixtieq nitkellem aħjar mal-ġirien.</td><td>将继续学马耳他语，想更好与邻居交流。<br><strong>Fil-futur</strong>：未来。<br><strong>se nkompli</strong>：我将继续。<br><strong>nistudja l-Malti</strong>：学马耳他语。<br><strong>għax nixtieq</strong>：因为想。<br><strong>nitkellem aħjar</strong>：更好交谈。<br><strong>mal-ġirien</strong>：与邻居们。</td></tr><tr><td>3b. Qed nippjana safra lejn l-Italja f’Settembru ma’ żewġ ħbieb tal-kors.</td><td>正计划九月和两位同学去意大利。<br><strong>Qed nippjana</strong>：我正在计划。<br><strong>safra lejn l-Italja</strong>：去意大利的旅行。<br><strong>f’Settembru</strong>：在九月。<br><strong>ma’ żewġ ħbieb tal-kors</strong>：与两位课程朋友。</td></tr><tr><td>3c. Se niċċelebraw għeluq snin ħabib tagħna u se nqattgħu ġimgħa hemmhekk.</td><td>将庆祝朋友生日，并在那里待一周。<br><strong>Se niċċelebraw</strong>：我们将庆祝。<br><strong>għeluq snin</strong>：生日。<br><strong>ħabib tagħna</strong>：我们的朋友。<br><strong>u se nqattgħu</strong>：并将度过。<br><strong>ġimgħa hemmhekk</strong>：在那里一周。</td></tr><tr><td>4a. L-ikel favorit tiegħi huwa l-għaġin bil-ħaxix, speċjalment meta nsajru d-dar.</td><td>最爱蔬菜意面，尤其在家做的。<br><strong>L-ikel favorit tiegħi</strong>：我最爱的食物。<br><strong>huwa l-għaġin bil-ħaxix</strong>：是蔬菜意面。<br><strong>speċjalment</strong>：尤其。<br><strong>meta nsajru</strong>：当我做它时，-u 指 għaġin，也可能按语境理解“我们做”。<br><strong>d-dar</strong>：在家。</td></tr><tr><td>4b. Żgur ma niekolx ikel li jien allerġiku għalih, u dejjem naqra l-ingredjenti.</td><td>不吃自己过敏的食物，总看配料。<br><strong>Żgur</strong>：肯定。<br><strong>ma niekolx</strong>：我不吃。<br><strong>ikel</strong>：食物。<br><strong>li jien allerġiku għalih</strong>：我对其过敏的，għalih＝对它。<br><strong>u dejjem naqra</strong>：并总阅读。<br><strong>l-ingredjenti</strong>：配料。</td></tr><tr><td>4c. Inħobb insajjar fi tmiem il-ġimgħa għax ikolli aktar ħin nipprova riċetti ġodda.</td><td>喜欢周末做饭，有更多时间试新食谱。<br><strong>Inħobb insajjar</strong>：我喜欢做饭。<br><strong>fi tmiem il-ġimgħa</strong>：周末。<br><strong>għax ikolli</strong>：因为我会有。<br><strong>aktar ħin</strong>：更多时间。<br><strong>nipprova</strong>：尝试。<br><strong>riċetti ġodda</strong>：新食谱。</td></tr><tr><td>5a. Biex niddeverti nħobb niltaqa’ ma’ sħabi, nara film jew immur mixja twila.</td><td>娱乐时爱见朋友、看电影或长距离散步。<br><strong>Biex niddeverti</strong>：为了消遣。<br><strong>nħobb niltaqa’</strong>：我喜欢见面。<br><strong>ma’ sħabi</strong>：和朋友。<br><strong>nara film</strong>：看电影。<br><strong>jew immur mixja twila</strong>：或去长途散步。</td></tr><tr><td>5b. Normalment immorru l-Belt is-Sibt filgħaxija u nieklu xi ħaġa wara l-film.</td><td>通常周六晚上去 Valletta，电影后吃点东西。<br><strong>Normalment</strong>：通常。<br><strong>immorru l-Belt</strong>：我们去 Valletta。<br><strong>is-Sibt filgħaxija</strong>：周六晚上。<br><strong>u nieklu xi ħaġa</strong>：并吃点东西。<br><strong>wara l-film</strong>：电影后。</td></tr><tr><td>5c. Meta nkun għajjien nippreferi noqgħod id-dar u naqra ktieb bil-kwiet.</td><td>累时宁愿在家安静看书。<br><strong>Meta nkun għajjien</strong>：当我累时，男性。<br><strong>nippreferi</strong>：我更喜欢。<br><strong>noqgħod id-dar</strong>：待在家里。<br><strong>u naqra ktieb</strong>：并读书。<br><strong>bil-kwiet</strong>：安静地。</td></tr><tr><td>6a. Nuża l-karozza tal-linja biex immur għax-xogħol, iżda għal postijiet qrib nimxi.</td><td>上班坐公交，近处走路。<br><strong>Nuża</strong>：我使用。<br><strong>l-karozza tal-linja</strong>：公交车。<br><strong>biex immur għax-xogħol</strong>：为了上班。<br><strong>iżda</strong>：但是。<br><strong>għal postijiet qrib</strong>：去附近地点。<br><strong>nimxi</strong>：我步行。</td></tr><tr><td>6b. Nippreferi l-ferrovija meta nsiefer għax nista’ naqra u nara l-veduta matul il-vjaġġ.</td><td>出国时偏爱火车，可阅读、沿途看风景。<br><strong>Nippreferi l-ferrovija</strong>：我更喜欢火车。<br><strong>meta nsiefer</strong>：当我旅行时。<br><strong>għax nista’ naqra</strong>：因为能读书。<br><strong>u nara l-veduta</strong>：并看景。<br><strong>matul il-vjaġġ</strong>：旅程中。</td></tr><tr><td>6c. It-traffiku jdejjaqni, speċjalment meta jkolli nistenna ħafna biex nasal id-dar.</td><td>讨厌堵车，尤其久等才能到家。<br><strong>It-traffiku</strong>：交通拥堵。<br><strong>jdejjaqni</strong>：令我不快。<br><strong>speċjalment meta</strong>：特别当。<br><strong>jkolli nistenna ħafna</strong>：我必须等很久。<br><strong>biex nasal id-dar</strong>：才能到家。</td></tr><tr><td>7a. Inħobb insiefer u diġà żort l-Italja u Spanja matul il-vaganzi tiegħi.</td><td>爱旅行，假期已去过意大利、西班牙。<br><strong>Inħobb insiefer</strong>：我喜欢出国。<br><strong>u diġà żort</strong>：并已游览。<br><strong>l-Italja u Spanja</strong>：意大利和西班牙。<br><strong>matul il-vaganzi tiegħi</strong>：我的假期中。</td></tr><tr><td>7b. L-iktar pajjiż li għoġobni kien l-Italja minħabba l-arti, l-ikel u l-bliet antiki.</td><td>最喜欢意大利，因艺术、食物与古城。<br><strong>L-iktar pajjiż li għoġobni</strong>：我最喜欢的国家。<br><strong>kien l-Italja</strong>：是意大利。<br><strong>minħabba</strong>：由于。<br><strong>l-arti</strong>：艺术。<br><strong>l-ikel</strong>：食物。<br><strong>u l-bliet antiki</strong>：与古老城市。</td></tr><tr><td>7c. M’hemmx pajjiż li nista’ ngħid li ma jogħġobnix, għax għad hemm ħafna x’niskopri.</td><td>不能说有哪个国家不喜欢，仍有很多待发现。<br><strong>M’hemmx pajjiż</strong>：没有一个国家。<br><strong>li nista’ ngħid</strong>：我能够说。<br><strong>li ma jogħġobnix</strong>：我不喜欢的。<br><strong>għax</strong>：因为。<br><strong>għad hemm</strong>：仍有。<br><strong>ħafna x’niskopri</strong>：很多可供我发现。</td></tr><tr><td>7d. Is-sena l-oħra qattajt ġimgħa Firenze ma’ sħabi, żorna mużewijiet u mxejna ħafna kuljum.</td><td>去年和朋友在佛罗伦萨一周，参观博物馆，每天步行很多。<br><strong>Is-sena l-oħra</strong>：去年。<br><strong>qattajt ġimgħa</strong>：我待了一周。<br><strong>Firenze ma’ sħabi</strong>：在佛罗伦萨与朋友。<br><strong>żorna mużewijiet</strong>：我们参观博物馆。<br><strong>u mxejna ħafna kuljum</strong>：并每天走很多路。</td></tr></tbody></table><hr><h2 id="_2-约-100-词写作与范文" tabindex="-1">2 约 100 词写作与范文 <a class="header-anchor" href="#_2-约-100-词写作与范文" aria-label="Permalink to &quot;2 约 100 词写作与范文&quot;">​</a></h2><h3 id="约-100-词写作" tabindex="-1">约 100 词写作 <a class="header-anchor" href="#约-100-词写作" aria-label="Permalink to &quot;约 100 词写作&quot;">​</a></h3><p><code>Il-Kitba: Agħżel waħda mill-ewwel paġna u ikteb madwar 100 kelma dwarha</code>：写作：从前面的主题中选一个，写约 100 词。<strong>Agħżel</strong>：选择；<strong>waħda</strong>：一个；<strong>mill-ewwel paġna</strong>：从第一页，内容指第 1 页；<strong>u ikteb</strong>：并写；<strong>madwar</strong>：大约；<strong>100 kelma</strong>：一百词；<strong>dwarha</strong>：关于它。</p><h3 id="范文-jien" tabindex="-1">范文：Jien <a class="header-anchor" href="#范文-jien" aria-label="Permalink to &quot;范文：Jien&quot;">​</a></h3><p>Jisimni Alex u noqgħod l-Imsida ma’ ħabib tiegħi. Għandi tletin sena u naħdem f’uffiċċju żgħir fil-Belt. Ix-xogħol tiegħi jibda fit-tmienja, għalhekk inqum kmieni u nieħu l-karozza tal-linja. Wara x-xogħol nattendi kors tal-Malti darbtejn fil-ġimgħa għax nixtieq nitkellem aħjar mal-ġirien. Fil-ħin liberu nħobb naqra, insajjar u nimxi ħdejn il-baħar. Dawn l-attivitajiet jgħinuni nistrieħ wara ġurnata twila u mimlija xogħol. Is-Sibt normalment niltaqa’ ma’ sħabi u kultant immorru naraw film. Il-familja tiegħi tgħix barra minn Malta, iżda nitkellmu fuq it-telefon kull filgħaxija. Fil-futur nixtieq nkompli nistudja u nsib aktar ħin għall-isport. Jiena persuna kalma u nħobb nitgħallem affarijiet ġodda ma’ nies differenti.</p><p>上文按空格分词为 <strong>100 词</strong>；带冠词的连字符词、带撇号词各按一个书写词计。</p><h3 id="逐句解析" tabindex="-1">逐句解析 <a class="header-anchor" href="#逐句解析" aria-label="Permalink to &quot;逐句解析&quot;">​</a></h3><table tabindex="0"><thead><tr><th>句子</th><th>中文与逐词／短语解析</th></tr></thead><tbody><tr><td>Jisimni Alex u noqgħod l-Imsida ma’ ħabib tiegħi.</td><td>我叫 Alex，和朋友住 Msida。<br><strong>Jisimni Alex</strong>：我叫 Alex。<br><strong>u noqgħod</strong>：并居住。<br><strong>l-Imsida</strong>：Msida 地名。<br><strong>ma’ ħabib tiegħi</strong>：与我的朋友。</td></tr><tr><td>Għandi tletin sena u naħdem f’uffiċċju żgħir fil-Belt.</td><td>我 30 岁，在 Valletta 的小办公室工作。<br><strong>Għandi</strong>：我有。<br><strong>tletin sena</strong>：三十年，用于年龄。<br><strong>u naħdem</strong>：并工作。<br><strong>f’uffiċċju żgħir</strong>：在小办公室。<br><strong>fil-Belt</strong>：在 Valletta。</td></tr><tr><td>Ix-xogħol tiegħi jibda fit-tmienja, għalhekk inqum kmieni u nieħu l-karozza tal-linja.</td><td>工作八点开始，所以早起搭公交。<br><strong>Ix-xogħol tiegħi</strong>：我的工作。<br><strong>jibda</strong>：开始。<br><strong>fit-tmienja</strong>：八点。<br><strong>għalhekk</strong>：因此。<br><strong>inqum kmieni</strong>：我早起。<br><strong>u nieħu</strong>：并搭乘。<br><strong>l-karozza tal-linja</strong>：公交车。</td></tr><tr><td>Wara x-xogħol nattendi kors tal-Malti darbtejn fil-ġimgħa għax nixtieq nitkellem aħjar mal-ġirien.</td><td>下班后每周两次上马耳他语课，想更好与邻居交谈。<br><strong>Wara x-xogħol</strong>：下班后。<br><strong>nattendi kors tal-Malti</strong>：我参加马耳他语课程。<br><strong>darbtejn fil-ġimgħa</strong>：每周两次。<br><strong>għax nixtieq</strong>：因为我想。<br><strong>nitkellem aħjar</strong>：说得更好。<br><strong>mal-ġirien</strong>：与邻居。</td></tr><tr><td>Fil-ħin liberu nħobb naqra, insajjar u nimxi ħdejn il-baħar.</td><td>空闲时爱阅读、做饭、海边走。<br><strong>Fil-ħin liberu</strong>：空闲时。<br><strong>nħobb naqra</strong>：我喜欢阅读。<br><strong>insajjar</strong>：我做饭。<br><strong>u nimxi</strong>：并走路。<br><strong>ħdejn il-baħar</strong>：在海边。</td></tr><tr><td>Dawn l-attivitajiet jgħinuni nistrieħ wara ġurnata twila u mimlija xogħol.</td><td>这些活动帮助我在漫长忙碌的一天后放松。<br><strong>Dawn l-attivitajiet</strong>：这些活动。<br><strong>jgħinuni</strong>：它们帮助我，-ni＝我。<br><strong>nistrieħ</strong>：我休息。<br><strong>wara ġurnata twila</strong>：在漫长一天后。<br><strong>u mimlija xogħol</strong>：并充满工作，mimlija 阴性配 ġurnata。</td></tr><tr><td>Is-Sibt normalment niltaqa’ ma’ sħabi u kultant immorru naraw film.</td><td>星期六通常见朋友，偶尔一起看电影。<br><strong>Is-Sibt</strong>：周六。<br><strong>normalment</strong>：通常。<br><strong>niltaqa’ ma’ sħabi</strong>：我见朋友。<br><strong>u kultant</strong>：而有时。<br><strong>immorru naraw film</strong>：我们去看电影。</td></tr><tr><td>Il-familja tiegħi tgħix barra minn Malta, iżda nitkellmu fuq it-telefon kull filgħaxija.</td><td>家人住国外，但每晚通电话。<br><strong>Il-familja tiegħi</strong>：我的家庭。<br><strong>tgħix</strong>：居住，配单数集合名词。<br><strong>barra minn Malta</strong>：马耳他以外。<br><strong>iżda nitkellmu</strong>：但是我们交谈。<br><strong>fuq it-telefon</strong>：通过电话。<br><strong>kull filgħaxija</strong>：每天晚上。</td></tr><tr><td>Fil-futur nixtieq nkompli nistudja u nsib aktar ħin għall-isport.</td><td>希望以后继续学习，多找时间运动。<br><strong>Fil-futur</strong>：未来。<br><strong>nixtieq nkompli</strong>：我想继续。<br><strong>nistudja</strong>：学习。<br><strong>u nsib</strong>：并找到。<br><strong>aktar ħin</strong>：更多时间。<br><strong>għall-isport</strong>：给运动。</td></tr><tr><td>Jiena persuna kalma u nħobb nitgħallem affarijiet ġodda ma’ nies differenti.</td><td>我是平静的人，喜欢与不同的人学习新事物。<br><strong>Jiena</strong>：我。<br><strong>persuna kalma</strong>：平静的人；kalma 配阴性名词 persuna，与实际性别无直接关系。<br><strong>u nħobb nitgħallem</strong>：并喜欢学习。<br><strong>affarijiet ġodda</strong>：新事物。<br><strong>ma’ nies differenti</strong>：与不同的人。</td></tr></tbody></table><hr><h2 id="_3-否定结构、规则与全部例句" tabindex="-1">3 否定结构、规则与全部例句 <a class="header-anchor" href="#_3-否定结构、规则与全部例句" aria-label="Permalink to &quot;3 否定结构、规则与全部例句&quot;">​</a></h2><h3 id="否定结构与原文规则" tabindex="-1">否定结构与原文规则 <a class="header-anchor" href="#否定结构与原文规则" aria-label="Permalink to &quot;否定结构与原文规则&quot;">​</a></h3><p><code>Il-Grammatika: In-Negattiv</code>＝语法：否定。核心 <strong>ma + 动词 + x</strong>；<strong>m’</strong> 是 ma 的缩合形式，<strong>x</strong> 附在动词／带后缀的词组上。</p><table tabindex="0"><thead><tr><th>原文</th><th>中文与逐词／短语解析</th></tr></thead><tbody><tr><td>Ma nafx.</td><td>我不知道。<br><strong>Ma … x</strong>：否定框架。<br><strong>naf</strong>：我知道。<br><strong>nafx</strong>：naf 加 x；不是英语式另加独立 not。</td></tr><tr><td>Ma rridx.</td><td>我不想。<br><strong>Ma … x</strong>：否定。<br><strong>rrid</strong>：我想要，肯定常见 irrid。<br><strong>rridx</strong>：否定中的词形。</td></tr><tr><td>M’għamilx.</td><td>他没做。<br><strong>M’</strong>：ma 缩合。<br><strong>għamilx</strong>：għamel 的否定形式，注意元音。</td></tr><tr><td>M’għedtlix.</td><td>你没有告诉我。<br><strong>M’</strong>：ma 缩合。<br><strong>għedt</strong>：过去时“我／你说了”同形；本句按教材及“给我”的语境取第二人称。<br><strong>-li</strong>：给我。<br><strong>-x</strong>：否定，放在代词后缀之后。</td></tr><tr><td>Il-verbi, li huma kliem li juru azzjoni jew stat, jistgħu juru n-negattiv, juri li l-azzjoni ma seħħitx.</td><td>原文句法略松散，意为动词表示动作或状态，也能构成否定，表动作未发生。<br><strong>Il-verbi</strong>：动词们。<br><strong>li huma kliem</strong>：它们是词语。<br><strong>li juru</strong>：表示。<br><strong>azzjoni jew stat</strong>：动作或状态。<br><strong>jistgħu juru n-negattiv</strong>：能够表示否定。<br><strong>juri li</strong>：表示……。<br><strong>l-azzjoni ma seħħitx</strong>：动作没有发生。</td></tr><tr><td>Normalment, in-negattiv isir billi quddiem il-verb tiżdied il-‘ma’ u wara l-verb tingħaqad ix-x. Eżempju:</td><td>通常在动词前加 ma，后接 x 构成否定。例如：<br><strong>Normalment</strong>：通常。<br><strong>in-negattiv isir</strong>：否定被构成。<br><strong>billi</strong>：通过。<br><strong>quddiem il-verb</strong>：在动词前。<br><strong>tiżdied il-ma</strong>：加 ma。<br><strong>u wara l-verb</strong>：动词之后。<br><strong>tingħaqad ix-x</strong>：连接 x。<br><strong>Eżempju</strong>：例子。</td></tr><tr><td>Meta l-verb jispiċċa bil-vokali ‘a’ fin-negattiv din tinbidel f’ ‘ie’.</td><td>教材说动词末尾 a 在否定里变 ie；这是局部规律的简化说明，须结合实例。<br><strong>Meta</strong>：当……时。<br><strong>l-verb jispiċċa</strong>：动词结尾为。<br><strong>bil-vokali a</strong>：元音 a。<br><strong>fin-negattiv</strong>：在否定式中。<br><strong>din tinbidel f’ ie</strong>：它变为 ie。</td></tr><tr><td>Il-verb li jispiċċa bl-appostrofi f’tarf il-kelma, sinjal li l-kelma għandha l-għajn, fin-negattiv l-appostrofu jaqa’.</td><td>动词末尾的撇号与历史 għ 有关；否定时撇号去掉。这里讲这些词的拼写，不是把任何词内撇号都删除。<br><strong>li jispiċċa bl-appostrofi</strong>：以撇号结尾。<br><strong>f’tarf il-kelma</strong>：词末。<br><strong>sinjal</strong>：标记。<br><strong>li l-kelma għandha l-għajn</strong>：表示这个词有 għ。<br><strong>fin-negattiv</strong>：否定中。<br><strong>l-appostrofu jaqa’</strong>：撇号脱落。</td></tr></tbody></table><h3 id="所有例句与空白补全" tabindex="-1">所有例句与空白补全 <a class="header-anchor" href="#所有例句与空白补全" aria-label="Permalink to &quot;所有例句与空白补全&quot;">​</a></h3><table tabindex="0"><thead><tr><th>肯定 → 否定</th><th>中文与词语</th></tr></thead><tbody><tr><td>It-tifel kiel. → It-tifel <strong>ma kielx</strong>.</td><td>男孩吃了 → 男孩没吃。<br><strong>It-tifel</strong>：男孩。<br><strong>kiel</strong>：他吃了。<br><strong>ma kielx</strong>：他没吃。</td></tr><tr><td>Marru lura d-dar. → <strong>Ma marrux</strong> lura d-dar.</td><td>他们回家了 → 没回家。<br><strong>marru</strong>：他们去了。<br><strong>lura d-dar</strong>：回家。<br><strong>ma marrux</strong>：他们没去。</td></tr><tr><td>Ra kollox mill-bogħod. → <strong>Ma rax</strong> kollox mill-bogħod.</td><td>他从远处看见一切 → 没有从远处看清所有东西。<br><strong>ra / ma rax</strong>：看见了／没看见。<br><strong>kollox</strong>：所有东西；“没有全部看到”不等于“一样没看到”。<br><strong>mill-bogħod</strong>：从远处。</td></tr><tr><td>Sergio tefa d-dawl. → Sergio <strong>ma tefiex</strong> id-dawl.</td><td>Sergio 关灯了 → 没关灯。<br><strong>tefa</strong>：熄灭、关掉，无末尾撇号。<br><strong>ma tefiex</strong>：没关掉，a → ie。<br><strong>d-dawl / id-dawl</strong>：灯光，冠词依语音环境出现不同形式。</td></tr><tr><td>L-għalliema tawna x-xogħol għad-dar. → L-għalliema <strong>ma tawniex</strong> ix-xogħol għad-dar.</td><td>老师们给了我们作业 → 没给我们作业。<br><strong>L-għalliema</strong>：这里由 tawna 可知为复数老师们。<br><strong>tawna</strong>：他们给了我们，taw + na。<br><strong>ma tawniex</strong>：没有给我们，-na 在此变 -nie 再接 x。<br><strong>ix-xogħol għad-dar</strong>：家庭作业。</td></tr><tr><td>Waqa’ fuq il-bankina. → <strong>Ma waqax</strong> fuq il-bankina.</td><td>他摔在人行道上 → 没摔。<br><strong>waqa’</strong>：他跌倒。<br><strong>ma waqax</strong>：没跌倒，去撇号接 x。<br><strong>fuq il-bankina</strong>：在人行道上。</td></tr><tr><td>Tefa’ l-ġebel fil-knisja. → <strong>Ma tefax</strong> il-ġebel fil-knisja.</td><td>他把石头扔进教堂 → 没扔。<br><strong>tefa’</strong>：扔，有撇号，区别于 tefa＝关灯。<br><strong>ma tefax</strong>：没扔。<br><strong>il-ġebel</strong>：石头。<br><strong>fil-knisja</strong>：进／在教堂里。</td></tr></tbody></table><hr><h2 id="_4-否定练习-a、b" tabindex="-1">4 否定练习 A、B <a class="header-anchor" href="#_4-否定练习-a、b" aria-label="Permalink to &quot;4 否定练习 A、B&quot;">​</a></h2><h3 id="否定练习-a-五题" tabindex="-1">否定练习 A：五题 <a class="header-anchor" href="#否定练习-a-五题" aria-label="Permalink to &quot;否定练习 A：五题&quot;">​</a></h3><p><code>Taħriġ marbut man-negattiv</code>＝与否定相关的练习。<strong>Taħriġ</strong>：练习；<strong>marbut ma’</strong>：与……相关。<code>Aqleb dawn is-sentenzi fin-negattiv</code>＝把这些句子变成否定；<strong>Aqleb</strong> 转换，<strong>dawn is-sentenzi</strong> 这些句子，<strong>fin-negattiv</strong> 成否定。</p><p>下列改写按练习把每个主要谓语均否定；不表示原叙事真实变成了相反事件。</p><table tabindex="0"><thead><tr><th>原句 → 参考否定</th><th>中文与逐词／短语解析</th></tr></thead><tbody><tr><td>1. Ilbieraħ it-tifel qam marid. Ħa riħ qawwi. → Ilbieraħ it-tifel <strong>ma qamx</strong> marid. <strong>Ma ħax</strong> riħ qawwi.</td><td>昨天男孩起床时病了，得了重感冒 → 起床时没有病，也没患重感冒。<br><strong>Ilbieraħ</strong>：昨天。<br><strong>it-tifel</strong>：男孩。<br><strong>qam / ma qamx</strong>：起床／没起床，否定与 marid 合解。<br><strong>marid</strong>：病着的。<br><strong>ħa / ma ħax</strong>：得了／没得。<br><strong>riħ qawwi</strong>：重感冒；riħ 也可指风，此处为固定搭配。</td></tr><tr><td>2. Jaqa’ kuljum. Għandu bżonn bastun. → <strong>Ma jaqax</strong> kuljum. <strong>M’għandux</strong> bżonn bastun.</td><td>他每天跌倒，需要拐杖 → 并非每天跌倒，也不需要拐杖。<br><strong>jaqa’ / ma jaqax</strong>：跌倒／不跌倒。<br><strong>kuljum</strong>：每天；否定每天不等于从未跌倒。<br><strong>għandu bżonn / m’għandux bżonn</strong>：需要／不需要。<br><strong>bastun</strong>：手杖。</td></tr><tr><td>3. Erfajtu u meddejtu fuq is-sodda. → <strong>Ma erfajtux</strong> u <strong>ma meddejtux</strong> fuq is-sodda.</td><td>我把他抱起放在床上 → 我没有抱起他，也没有把他放在床上。<br><strong>erfajtu</strong>：我／你抱起他，-u＝他。<br><strong>ma erfajtux</strong>：没有抱起他，x 在 -u 后。<br><strong>u</strong>：并且。<br><strong>meddejtu / ma meddejtux</strong>：把他放平／没有放平。<br><strong>fuq is-sodda</strong>：床上。<br><strong>-t</strong>：这里我／你过去时同形，译文取“我”。</td></tr><tr><td>4. Beka ħafna lil ommu. → <strong>Ma bekiex</strong> ħafna lil ommu.</td><td>他为母亲哭得很多 → 他没有为母亲哭很多。<br><strong>beka / ma bekiex</strong>：哭了／没哭，a → ie。<br><strong>ħafna</strong>：很多。<br><strong>lil ommu</strong>：为／对着他的母亲，具体关系依语境。</td></tr><tr><td>5. Mexa lura d-dar u sar għasra bix-xita. → <strong>Ma mexiex</strong> lura d-dar u <strong>ma sarx</strong> għasra bix-xita.</td><td>他步行回家，被雨淋透 → 他没有步行回家，也没有被雨淋透。<br><strong>mexa / ma mexiex</strong>：步行了／没步行。<br><strong>lura d-dar</strong>：回家。<br><strong>u</strong>：和。<br><strong>sar / ma sarx</strong>：变成／没有变成。<br><strong>għasra</strong>：湿透的状态。<br><strong>bix-xita</strong>：由于雨水。</td></tr></tbody></table><h3 id="否定练习-b-十题" tabindex="-1">否定练习 B：十题 <a class="header-anchor" href="#否定练习-b-十题" aria-label="Permalink to &quot;否定练习 B：十题&quot;">​</a></h3><table tabindex="0"><thead><tr><th>原谓语与完整答案</th><th>中文与逐词／短语解析</th></tr></thead><tbody><tr><td>1. kilt → Jien <strong>ma kiltx</strong> ir-ross.</td><td>我没吃米饭。<br><strong>Jien</strong>：我。<br><strong>kilt / ma kiltx</strong>：我吃了／没吃。<br><strong>ir-ross</strong>：米饭。</td></tr><tr><td>2. raqdet → Tina <strong>ma raqditx</strong> sewwa.</td><td>Tina 没睡好。<br><strong>Tina</strong>：女性人名。<br><strong>raqdet / ma raqditx</strong>：她睡了／没睡，注意 e → i。<br><strong>sewwa</strong>：好、安稳。</td></tr><tr><td>3. ħadem → Gino <strong>ma ħadimx</strong> sa tard billejl.</td><td>Gino 没工作到深夜。<br><strong>Gino</strong>：人名。<br><strong>ħadem / ma ħadimx</strong>：他工作了／没工作。<br><strong>sa tard</strong>：直到很晚。<br><strong>billejl</strong>：夜里。</td></tr><tr><td>4. studjaw → It-tfal <strong>ma studjawx</strong> għall-eżami.</td><td>孩子们没为考试学习。<br><strong>It-tfal</strong>：儿童们。<br><strong>studjaw / ma studjawx</strong>：他们学习了／没学习。<br><strong>għall-eżami</strong>：为考试。</td></tr><tr><td>5. waslet → L-għalliema <strong>ma waslitx</strong> kmieni.</td><td>女老师没有早到。<br><strong>L-għalliema</strong>：此处由 waslet 为女老师单数。<br><strong>waslet / ma waslitx</strong>：她到了／没到。<br><strong>kmieni</strong>：早。</td></tr><tr><td>6. saqsa → Il-wejter <strong>ma saqsiex</strong> bl-edukazzjoni.</td><td>服务员没有礼貌地询问。<br><strong>Il-wejter</strong>：男服务员。<br><strong>saqsa / ma saqsiex</strong>：询问了／没询问。<br><strong>bl-edukazzjoni</strong>：礼貌地，不译“用教育”。</td></tr><tr><td>7. xtrat → Ommi <strong>ma xtratx</strong> il-laħam.</td><td>母亲没买肉。<br><strong>Ommi</strong>：我母亲。<br><strong>xtrat / ma xtratx</strong>：她买了／没买。<br><strong>il-laħam</strong>：肉。</td></tr><tr><td>8. nieħu → Jien <strong>ma niħux</strong> ġelat kuljum.</td><td>我不是每天都吃冰淇淋。<br><strong>Jien</strong>：我。<br><strong>nieħu / ma niħux</strong>：我拿／吃，我不拿／吃，留意词干变化。<br><strong>ġelat</strong>：冰淇淋。<br><strong>kuljum</strong>：每天。</td></tr><tr><td>9. 原文 Hija jimxi，先改 timxi → Hija <strong>ma timxix</strong> ħames kilometri kull filgħodu.</td><td>她不是每天早上走五公里。<br><strong>Hija</strong>：她。<br><strong>jimxi</strong>：他走，与 Hija 不一致。<br><strong>timxi / ma timxix</strong>：她走／她不走。<br><strong>ħames kilometri</strong>：五公里，展开 5km。<br><strong>kull filgħodu</strong>：每天早晨。</td></tr><tr><td>10. jsuq → Missieri <strong>ma jsuqx</strong> il-vannijiet tal-iskola.</td><td>父亲不驾驶学校面包车。<br><strong>Missieri</strong>：我父亲。<br><strong>jsuq / ma jsuqx</strong>：他开车／不开。<br><strong>il-vannijiet</strong>：面包车们。<br><strong>tal-iskola</strong>：学校的。</td></tr></tbody></table><hr><h2 id="_5-定冠词-完整补全" tabindex="-1">5 定冠词：完整补全 <a class="header-anchor" href="#_5-定冠词-完整补全" aria-label="Permalink to &quot;5 定冠词：完整补全&quot;">​</a></h2><h3 id="定冠词-完整补全" tabindex="-1">定冠词：完整补全 <a class="header-anchor" href="#定冠词-完整补全" aria-label="Permalink to &quot;定冠词：完整补全&quot;">​</a></h3><p><code>L-Artiklu – Imla l-vojt bl-artiklu li jixraq</code>＝定冠词——用合适冠词填空。<strong>l-artiklu</strong> 冠词，<strong>Imla l-vojt</strong> 填空，<strong>bl-artiklu</strong> 用冠词，<strong>li jixraq</strong> 合适的。<code>Ikteb l-artiklu quddiem in-nomi</code>＝在名词前写冠词；<strong>quddiem</strong> 前面，<strong>in-nomi</strong> 名词们。</p><p>基本 <strong>il-</strong>；元音前常 <strong>l-</strong>；某些辅音前同化，例如 <strong>it-tadam、iż-żebbuġ、is-salamun</strong>。前面的词以元音结束时可省去冠词起始 i，如 <strong>nitfa’ t-tadam</strong>。介词与冠词缩合：<strong>minn + il- → mill-</strong>，<strong>bi + il- → bil- / bl-</strong>。不要把 ħ、ġ 与其他字母混为一谈。</p><table tabindex="0"><thead><tr><th>A 组完整句子</th><th>中文与逐词／短语解析</th></tr></thead><tbody><tr><td>1. Fl-insalata nitfa’ <strong>t-tadam, il-ħass, il-ħjar, it-tonn taż-żejt, iż-żebbuġ, il-kappar, il-fażola bajda, il-ġbejna tal-bżar</strong> u bajda mgħollija.</td><td>沙拉里放番茄、生菜、黄瓜、油浸金枪鱼、橄榄、刺山柑、白豆、胡椒羊奶酪和水煮蛋。<br><strong>Fl-insalata</strong>：在沙拉里。<br><strong>nitfa’</strong>：我放入。<br><strong>t-tadam</strong>：番茄，前词末元音后使用 t-。<br><strong>il-ħass</strong>：生菜。<br><strong>il-ħjar</strong>：黄瓜。<br><strong>it-tonn taż-żejt</strong>：油浸金枪鱼。<br><strong>iż-żebbuġ</strong>：橄榄。<br><strong>il-kappar</strong>：刺山柑。<br><strong>il-fażola bajda</strong>：白豆。<br><strong>il-ġbejna tal-bżar</strong>：胡椒调味小奶酪。<br><strong>u bajda mgħollija</strong>：和一个水煮蛋，无须把所有 bajda 都认作“白色”。</td></tr><tr><td>2. Għall-iskola għandi bżonn <strong>il-kotba</strong> tal-Malti u <strong>l-Ingliż, il-pokit</strong> u <strong>l-karti</strong>.</td><td>上学需要马耳他语／英语书、笔袋和纸张。<br><strong>Għall-iskola</strong>：为了上学。<br><strong>għandi bżonn</strong>：我需要。<br><strong>il-kotba</strong>：书们。<br><strong>tal-Malti</strong>：马耳他语的。<br><strong>u l-Ingliż</strong>：和英语，按原题只填冠词。<br><strong>il-pokit</strong>：笔袋。<br><strong>u l-karti</strong>：与纸张。<br><strong>自然表达</strong>：若明确两门课的书，可写 il-kotba tal-Malti u tal-Ingliż；后一个 tal- 是额外修订，不是单填冠词。</td></tr><tr><td>3. <strong>It-Taljan</strong> u <strong>l-Ispanjol</strong> <strong>huma ż-żewġ</strong> lingwi favoriti tiegħi.</td><td>意大利语和西班牙语是我最爱的两门语言。<br><strong>It-Taljan</strong>：意大利语。<br><strong>u l-Ispanjol</strong>：和西班牙语。<br><strong>huma</strong>：它们是；原文 huwa 是单数，另行修正。<br><strong>ż-żewġ lingwi</strong>：这两门语言。<br><strong>favoriti tiegħi</strong>：我最爱的，复数。</td></tr><tr><td>4. Itħan <strong>iċ-ċiċri</strong> friska, <strong>l-ispinaċi</strong> u <strong>l-ful</strong>.</td><td>把新鲜鹰嘴豆、菠菜和蚕豆磨碎。<br><strong>Itħan</strong>：磨碎，命令。<br><strong>iċ-ċiċri</strong>：鹰嘴豆，ċ 前同化。<br><strong>friska</strong>：新鲜的，保留原题集合词搭配。<br><strong>l-ispinaċi</strong>：菠菜，元音前 l-。<br><strong>u l-ful</strong>：和蚕豆，前有元音结尾 u 时冠词可省 i。</td></tr><tr><td>5. <strong>Is-salamun</strong> inħobb nimmarinah bil-lumi, <strong>l-għasel</strong> u <strong>t-tewm</strong>.</td><td>我喜欢用柠檬、蜂蜜、大蒜腌三文鱼。<br><strong>Is-salamun</strong>：三文鱼。<br><strong>inħobb</strong>：我喜欢。<br><strong>nimmarinah</strong>：腌它，-h 回指鱼。<br><strong>bil-lumi</strong>：用柠檬。<br><strong>l-għasel</strong>：蜂蜜。<br><strong>u t-tewm</strong>：和大蒜。<br><strong>说明</strong>：这里按原题列举补冠词；若强调每一种腌料，可另写 bil-lumi, bl-għasel u bit-tewm。</td></tr></tbody></table><table tabindex="0"><thead><tr><th>B 组完整句子</th><th>中文与逐词／短语解析</th></tr></thead><tbody><tr><td>1. <strong>It-tifel</strong> kiel tard ħafna u raqad fuq <strong>is-sodda</strong>.</td><td>男孩吃得很晚，睡在床上。<br><strong>It-tifel</strong>：男孩，t 同化。<br><strong>kiel tard ħafna</strong>：吃得很晚。<br><strong>u raqad</strong>：并睡了。<br><strong>fuq is-sodda</strong>：在床上，s 同化。</td></tr><tr><td>2. Morna nixtru <strong>l-ikel</strong> għal filgħaxija.</td><td>我们去买晚上的食物。<br><strong>Morna</strong>：我们去了。<br><strong>nixtru</strong>：买。<br><strong>l-ikel</strong>：食物，元音前 l-。<br><strong>għal filgħaxija</strong>：为晚上。</td></tr><tr><td>3. Martha u Grace għalqu <strong>t-tieqa</strong> tad-dar tagħhom.</td><td>Martha 和 Grace 关了自家窗户。<br><strong>Martha u Grace</strong>：两个人名。<br><strong>għalqu</strong>：他们关了，词末 u 后 t-。<br><strong>t-tieqa</strong>：窗户。<br><strong>tad-dar tagħhom</strong>：他们家的。</td></tr><tr><td>4. <strong>Il-missier</strong> tat-tifel talbu jġiblu <strong>l-ilma</strong> u <strong>l-ħobż mill-bank</strong> tal-kċina.</td><td>男孩的父亲请他从厨房台面拿水和面包。<br><strong>Il-missier</strong>：父亲。<br><strong>tat-tifel</strong>：男孩的。<br><strong>talbu</strong>：他请求他，talab + u；不应只因末尾 u 就译成“他们请求”。<br><strong>jġiblu</strong>：给他拿来。<br><strong>l-ilma u l-ħobż</strong>：水与面包。<br><strong>mill-bank</strong>：从台面，minn + il-bank 必须缩合。<br><strong>tal-kċina</strong>：厨房的。</td></tr><tr><td>5. <strong>Il-mara</strong> u <strong>r-raġel</strong> marru jixtru <strong>l-Belt</strong> u xtraw <strong>iż-żarbun</strong> u <strong>s-siġra</strong> tal-Milied li għandhom ġewwa <strong>s-salott</strong>.</td><td>女人与男人去 Valletta 购物，买了鞋与放在客厅的圣诞树。<br><strong>Il-mara u r-raġel</strong>：女人与男人。<br><strong>marru jixtru</strong>：去购物。<br><strong>l-Belt</strong>：去 Valletta；此处不是“买下城市”。<br><strong>u xtraw</strong>：并买了。<br><strong>iż-żarbun</strong>：鞋类。<br><strong>u s-siġra tal-Milied</strong>：与圣诞树。<br><strong>li għandhom</strong>：他们有的。<br><strong>ġewwa s-salott</strong>：在客厅里。</td></tr></tbody></table><hr><h2 id="_6-代词阅读、分类与造句" tabindex="-1">6 代词阅读、分类与造句 <a class="header-anchor" href="#_6-代词阅读、分类与造句" aria-label="Permalink to &quot;6 代词阅读、分类与造句&quot;">​</a></h2><h3 id="代词阅读-逐句解析" tabindex="-1">代词阅读：逐句解析 <a class="header-anchor" href="#代词阅读-逐句解析" aria-label="Permalink to &quot;代词阅读：逐句解析&quot;">​</a></h3><p><code>Il-Pronomi Personali, Demostrattivi u Interrogattivi – Sibhom mis-silta u mmarkahom b’kuluri differenti</code>＝找出文中的人称、指示、疑问代词，用不同颜色标记。</p><p><strong>Il-pronomi</strong>：代词。<br><strong>personali</strong>：人称的。<br><strong>demostrattivi</strong>：指示的，依原文标题。<br><strong>interrogattivi</strong>：疑问的。<br><strong>Sibhom</strong>：找出它们。<br><strong>mis-silta</strong>：从文章里。<br><strong>u mmarkahom</strong>：并标记它们。<br><strong>b’kuluri differenti</strong>：用不同颜色。以下用文字标签，避免颜色在不同阅读器中失效。</p><table tabindex="0"><thead><tr><th>原句</th><th>中文与逐词／短语解析</th></tr></thead><tbody><tr><td>“Liema waħda trid?”, saqsietni Rita tal-laħam.</td><td>“你想要哪一块？”肉店的 Rita 问我。<br><strong>Liema</strong>：哪一个，疑问限定词／代词。<br><strong>waħda</strong>：一块／一个，阴性。<br><strong>trid</strong>：你想要。<br><strong>saqsietni</strong>：她问了我，-ni＝我。<br><strong>Rita tal-laħam</strong>：卖肉的 Rita。</td></tr><tr><td>Jien weġibtha “dik tan-naħa tal-lemin, għax ikbar!”.</td><td>我答她：“右边那块，因为更大！”<br><strong>Jien</strong>：我。<br><strong>weġibtha</strong>：我回答她，-ha＝她。<br><strong>dik</strong>：那一块，阴性。<br><strong>tan-naħa tal-lemin</strong>：右边的。<br><strong>għax</strong>：因为。<br><strong>ikbar</strong>：更大。</td></tr><tr><td>Hi b’daħka daqsiex weġbitni “Din trid, u din nagħtik!”.</td><td>她咧嘴笑着答：“你要这块，就给你这块！”<br><strong>Hi</strong>：她，hija 的短形。<br><strong>b’daħka daqsiex</strong>：带着大大的笑容。<br><strong>weġbitni</strong>：她回答我。<br><strong>Din trid</strong>：这块是你要的。<br><strong>u din nagħtik</strong>：这块我给你，-k＝给你。</td></tr><tr><td>Biċċa laħam friska u tajba għall-ikla ta’ filgħaxija.</td><td>一块新鲜好肉，用来做晚餐。原文是无完整谓语的名词短语。<br><strong>Biċċa laħam</strong>：一块肉。<br><strong>friska u tajba</strong>：新鲜而好的，阴性配 biċċa。<br><strong>għall-ikla</strong>：给这一餐。<br><strong>ta’ filgħaxija</strong>：晚上的。</td></tr><tr><td>Din kienet l-ikla favorita tiegħi u kont nieħu gost insajjarha wkoll.</td><td>这是我最爱的餐食，我也很喜欢做它。<br><strong>Din</strong>：这个，阴性。<br><strong>kienet</strong>：当时是。<br><strong>l-ikla favorita tiegħi</strong>：我最爱的餐食。<br><strong>u kont nieħu gost</strong>：而我当时／常常很享受。<br><strong>insajjarha</strong>：我做它，-ha 回指 ikla。<br><strong>wkoll</strong>：也。</td></tr><tr><td>Mal-laħam inżid il-bżar tal-kulur, il-basal u l-patata u nsajjar kollox fil-forn.</td><td>配肉加入彩椒、洋葱和土豆，一起放烤箱烹调。<br><strong>Mal-laħam</strong>：和肉一起。<br><strong>inżid</strong>：我加入。<br><strong>il-bżar tal-kulur</strong>：彩椒。<br><strong>il-basal</strong>：洋葱。<br><strong>u l-patata</strong>：和土豆。<br><strong>u nsajjar</strong>：并烹调。<br><strong>kollox</strong>：所有东西。<br><strong>fil-forn</strong>：在烤箱里。</td></tr><tr><td>“Xi ħaġa oħra?”, reġgħet Rita.</td><td>“还要别的吗？”Rita 又问。<br><strong>Xi ħaġa oħra</strong>：其他什么东西；xi 在此修饰 ħaġa，不是孤立问词。<br><strong>reġgħet</strong>：她又／再次，省略“说、问”。<br><strong>Rita</strong>：人名。</td></tr><tr><td>“Le dak kollox”, weġibtha jien.</td><td>“不用，就这些。”我答她。<br><strong>Le</strong>：不。<br><strong>dak kollox</strong>：那就是全部。<br><strong>weġibtha</strong>：我回答她。<br><strong>jien</strong>：我，后置强调。</td></tr></tbody></table><h3 id="分类答案" tabindex="-1">分类答案 <a class="header-anchor" href="#分类答案" aria-label="Permalink to &quot;分类答案&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类别</th><th>文章中的项目与说明</th></tr></thead><tbody><tr><td>独立人称</td><td><strong>Jien / jien</strong>：我，出现两次。<br><strong>Hi</strong>：她。</td></tr><tr><td>附着人称／宾语成分</td><td><strong>-ni</strong>：saqsietni、weġbitni 中“我”。<br><strong>-ha</strong>：weġibtha 中“她”，insajjarha 中“它”。<br><strong>-k</strong>：nagħtik 中“给你”。<br>动词上的 n-、t- 等人称标记不应直接涂成独立人称代词。</td></tr><tr><td>指示</td><td><strong>dik</strong>：那块。<br><strong>Din / din</strong>：这块／这餐，多次。<br><strong>dak</strong>：那个／那些话所指的全部。</td></tr><tr><td>疑问</td><td><strong>Liema</strong>：哪一个。<br><strong>Xi</strong>：Xi ħaġa oħra 中的疑问性限定成分；严格说此处不是独立代词。</td></tr><tr><td>所有／其他</td><td><strong>tiegħi</strong>：我的，所属形式。<br><strong>kollox</strong>：一切，不定代词。<br><strong>waħda</strong>：一个／一块，可独立指代前面未明说的肉块。</td></tr></tbody></table><h3 id="五个较完整造句" tabindex="-1">五个较完整造句 <a class="header-anchor" href="#五个较完整造句" aria-label="Permalink to &quot;五个较完整造句&quot;">​</a></h3><p><code>Agħżel ħames partiċelli u ikteb sentenza b’kull waħda</code>＝选五项，每项造句。<strong>agħżel</strong> 选，<strong>ħames</strong> 五，<strong>partiċelli</strong> 原文泛称小词／成分，<strong>b’kull waħda</strong> 用每一项。这里选本页代词，不把模糊题目解释成固定唯一词表。</p><table tabindex="0"><thead><tr><th>例句</th><th>中文与逐词／短语解析</th></tr></thead><tbody><tr><td><strong>Jien</strong> immur għall-kors tal-Malti wara x-xogħol għax nixtieq nitkellem aħjar mal-ġirien.</td><td>我下班后上马耳他语课，想更好与邻居交流。<br><strong>Jien</strong>：我。<br><strong>immur għall-kors tal-Malti</strong>：去马耳他语课程。<br><strong>wara x-xogħol</strong>：下班后。<br><strong>għax nixtieq</strong>：因为我想。<br><strong>nitkellem aħjar</strong>：说得更好。<br><strong>mal-ġirien</strong>：与邻居。</td></tr><tr><td><strong>Hi</strong> tħobb issajjar għall-familja u kull nhar ta’ Ħadd tipprova riċetta ġdida.</td><td>她爱为家人做饭，每个周日尝试新食谱。<br><strong>Hi</strong>：她。<br><strong>tħobb issajjar</strong>：喜欢做饭。<br><strong>għall-familja</strong>：为家人。<br><strong>u kull nhar ta’ Ħadd</strong>：并每周日。<br><strong>tipprova</strong>：她尝试。<br><strong>riċetta ġdida</strong>：新食谱。</td></tr><tr><td><strong>Din</strong> hija l-bagalja tiegħi, u fiha poġġejt il-ħwejjeġ kollha għall-vaganza ta’ ġimgħa.</td><td>这是我的箱子，装了一周假期的全部衣物。<br><strong>Din</strong>：这个，阴性。<br><strong>hija l-bagalja tiegħi</strong>：是我的箱子。<br><strong>u fiha</strong>：并在它里面。<br><strong>poġġejt</strong>：我放了。<br><strong>il-ħwejjeġ kollha</strong>：所有衣物。<br><strong>għall-vaganza ta’ ġimgħa</strong>：为一周假期。</td></tr><tr><td><strong>Dik</strong> il-lukanda qrib l-istazzjon hija komda u għandha kmamar kbar għall-familji.</td><td>车站附近那家酒店舒适，有适合家庭的大房间。<br><strong>Dik il-lukanda</strong>：那家酒店。<br><strong>qrib l-istazzjon</strong>：车站附近。<br><strong>hija komda</strong>：舒适。<br><strong>u għandha</strong>：并有。<br><strong>kmamar kbar</strong>：大房间，复数。<br><strong>għall-familji</strong>：给家庭。</td></tr><tr><td><strong>Liema</strong> ferrovija għandna nieħdu biex naslu Firenze qabel il-ħin tal-ikla ta’ nofsinhar?</td><td>应搭哪班火车，才能午饭前到佛罗伦萨？<br><strong>Liema ferrovija</strong>：哪班火车。<br><strong>għandna nieħdu</strong>：我们应该搭乘。<br><strong>biex naslu Firenze</strong>：为了到佛罗伦萨。<br><strong>qabel</strong>：之前。<br><strong>il-ħin tal-ikla ta’ nofsinhar</strong>：午餐时间。</td></tr></tbody></table><hr><h2 id="_7-所属代词-配对与选择题" tabindex="-1">7 所属代词：配对与选择题 <a class="header-anchor" href="#_7-所属代词-配对与选择题" aria-label="Permalink to &quot;7 所属代词：配对与选择题&quot;">​</a></h2><h3 id="所属代词图片与配对" tabindex="-1">所属代词图片与配对 <a class="header-anchor" href="#所属代词图片与配对" aria-label="Permalink to &quot;所属代词图片与配对&quot;">​</a></h3><p><code>Il-pronomi possessivi</code>＝所属代词。<code>Qabbel l-istampi mas-sentenzi billi tikteb in-numru fuq il-linja</code>＝把图片与句子配对，将数字写在线上。</p><p><strong>Qabbel</strong>：配对。<br><strong>l-istampi</strong>：图片。<br><strong>mas-sentenzi</strong>：与句子。<br><strong>billi tikteb</strong>：通过写。<br><strong>in-numru</strong>：数字。<br><strong>fuq il-linja</strong>：在线上。</p><p>图片题按空白顺序：<strong>Tagħhom → 2，Tagħha → 3，Tiegħu → 1</strong>。前者属复数所有者，后两者分别女性、男性所有者。</p><p>第二题 <code>Qabbel il-pronomi possessivi mas-sentenzi tal-ewwel kolonna</code>＝把所属形式与第一栏句子配对；<strong>tal-ewwel kolonna</strong> 第一栏的。</p><table tabindex="0"><thead><tr><th>第一栏 → 正确配对</th><th>中文与词语</th></tr></thead><tbody><tr><td>1. Jien għandi kelb. → Dak <strong>tiegħi</strong>.</td><td>我有狗。那是我的。<br><strong>Jien</strong>：我。<br><strong>għandi</strong>：我有。<br><strong>kelb</strong>：狗。<br><strong>Dak tiegħi</strong>：那是我的，tiegħi 不随“我”的性别改变。</td></tr><tr><td>2. Int għandek qattus. → Dak <strong>tiegħek</strong>.</td><td>你有猫。那是你的。<br><strong>Int</strong>：你。<br><strong>għandek</strong>：你有。<br><strong>qattus</strong>：猫。<br><strong>Dak tiegħek</strong>：那是你的。</td></tr><tr><td>3. Hu għandu żiemel. → Dak <strong>tiegħu</strong>.</td><td>他有马。那是他的。<br><strong>Hu</strong>：他。<br><strong>għandu</strong>：他有。<br><strong>żiemel</strong>：马。<br><strong>Dak tiegħu</strong>：那是他的。</td></tr><tr><td>4. Hi għandha ħanżir. → Dak <strong>tagħha</strong>.</td><td>她有猪。那是她的。<br><strong>Hi</strong>：她。<br><strong>għandha</strong>：她有。<br><strong>ħanżir</strong>：猪。<br><strong>Dak tagħha</strong>：那是她的。</td></tr><tr><td>5. Aħna għandna serduk. → Dak <strong>tagħna</strong>.</td><td>我们有公鸡。那是我们的。<br><strong>Aħna</strong>：我们。<br><strong>għandna</strong>：我们有。<br><strong>serduk</strong>：公鸡。<br><strong>Dak tagħna</strong>：那是我们的。</td></tr><tr><td>6. Intom għandkom ħmar. → Dak <strong>tagħkom</strong>.</td><td>你们有驴。那是你们的。<br><strong>Intom</strong>：你们。<br><strong>għandkom</strong>：你们有。<br><strong>ħmar</strong>：驴。<br><strong>Dak tagħkom</strong>：那是你们的。</td></tr><tr><td>7. Huma għandhom barri. → Dak <strong>tagħhom</strong>.</td><td>他们有公牛。那是他们的。<br><strong>Huma</strong>：他们／她们。<br><strong>għandhom</strong>：他们有。<br><strong>barri</strong>：公牛。<br><strong>Dak tagħhom</strong>：那是他们的。</td></tr></tbody></table><h3 id="五道选择题" tabindex="-1">五道选择题 <a class="header-anchor" href="#五道选择题" aria-label="Permalink to &quot;五道选择题&quot;">​</a></h3><p><code>Aqta’ linja taħt it-tweġiba t-tajba</code>＝在正确答案下画线；<strong>Aqta’ linja</strong> 此处画一条线，<strong>taħt</strong> 在下面，<strong>it-tweġiba t-tajba</strong> 正确回答。</p><table tabindex="0"><thead><tr><th>完整答案</th><th>中文与逐词／短语解析</th></tr></thead><tbody><tr><td>1. Dak il-kelb tat-tifel. Il-kelb <strong>tiegħu</strong> jismu Jack.</td><td>那条狗是男孩的。他的狗叫 Jack。<br><strong>Dak il-kelb</strong>：那条狗。<br><strong>tat-tifel</strong>：男孩的。<br><strong>Il-kelb tiegħu</strong>：他的狗；看所有者 tifel 的性别。<br><strong>jismu Jack</strong>：它叫 Jack。</td></tr><tr><td>2. Id-dar ta’ dik il-<strong>koppja</strong> hija kbira. Id-dar <strong>tagħhom</strong> fiha sebat ikmamar.</td><td>那对夫妇的房子很大，有七间房。<br><strong>Id-dar</strong>：房子。<br><strong>ta’ dik il-koppja</strong>：那对夫妇的；原文 kopja 意为副本，按此语境另行修正。<br><strong>hija kbira</strong>：很大。<br><strong>tagħhom</strong>：他们的，夫妇为复数所有者。<br><strong>fiha</strong>：它里面有。<br><strong>sebat ikmamar</strong>：七间房，元音前数词形。</td></tr><tr><td>3. Daniel ħabib kbir. <strong>Huwa</strong> l-akbar ħabib <strong>tiegħi</strong> u nħobbu ħafna.</td><td>Daniel 是好朋友，是我最亲近的朋友，我很喜欢他。<br><strong>Daniel</strong>：男性人名。<br><strong>ħabib kbir</strong>：好朋友。<br><strong>Huwa</strong>：他。<br><strong>l-akbar ħabib tiegħi</strong>：我最亲近的朋友，字面“最大朋友”。<br><strong>u nħobbu ħafna</strong>：我很喜欢他；也可能为“我们很喜欢他”。<br><strong>不唯一</strong>：若说“我们的／他们的朋友”，tagħna / tagħhom 也可有合适上下文；题目不足以唯一限定。</td></tr><tr><td>4. Oħti <strong>għandha</strong> dar żgħira imma sabiħa.</td><td>我姐妹有小而美的房子。<br><strong>Oħti</strong>：我的姐妹。<br><strong>għandha</strong>：她有。<br><strong>dar żgħira</strong>：小房子。<br><strong>imma sabiħa</strong>：但漂亮，均阴性配 dar。</td></tr><tr><td>5. Benjamin u l-familja <strong>tiegħu</strong> joqogħdu ġewwa Raħal Ġdid.</td><td>Benjamin 和家人住 Paola。<br><strong>Benjamin</strong>：男性所有者。<br><strong>u l-familja tiegħu</strong>：与他的家庭；不能因 familja 阴性改成 tagħha。<br><strong>joqogħdu</strong>：他们居住。<br><strong>ġewwa Raħal Ġdid</strong>：在 Paola，地名，字面“新村”。</td></tr></tbody></table><hr><h2 id="_8-颜色表与五项描写" tabindex="-1">8 颜色表与五项描写 <a class="header-anchor" href="#_8-颜色表与五项描写" aria-label="Permalink to &quot;8 颜色表与五项描写&quot;">​</a></h2><h3 id="颜色表-全部补全" tabindex="-1">颜色表：全部补全 <a class="header-anchor" href="#颜色表-全部补全" aria-label="Permalink to &quot;颜色表：全部补全&quot;">​</a></h3><p><code>L-Aġġettiv – Il-Kuluri</code>＝形容词——颜色。<strong>Maskil</strong>：阳性；<strong>Femminil</strong>：阴性。颜色通常与被修饰名词一致，有些借词不变。</p><table tabindex="0"><thead><tr><th>阳性</th><th>阴性</th><th>中文与说明</th></tr></thead><tbody><tr><td>abjad</td><td>bajda</td><td>白；bajda 也可作“一枚蛋”，须看语境</td></tr><tr><td>iswed</td><td>sewda</td><td>黑</td></tr><tr><td>aħmar</td><td>ħamra</td><td>红</td></tr><tr><td>blu / ikħal</td><td>blu / kaħla</td><td>蓝；blu 不变，ikħal 有 kaħla</td></tr><tr><td>isfar</td><td>safra</td><td>黄</td></tr><tr><td>aħdar</td><td>ħadra</td><td>绿</td></tr><tr><td>oranġjo</td><td>oranġjo</td><td>橙</td></tr><tr><td>vjola</td><td>vjola</td><td>紫</td></tr><tr><td>kannella</td><td>kannella</td><td>棕</td></tr><tr><td>griż</td><td>griża</td><td>灰</td></tr><tr><td>ċelesti</td><td>ċelesti</td><td>天蓝</td></tr><tr><td>roża</td><td>roża</td><td>粉红</td></tr><tr><td>lelà</td><td>lelà</td><td>淡紫／丁香紫；保留重音</td></tr></tbody></table><h3 id="五项描写-完整例句" tabindex="-1">五项描写：完整例句 <a class="header-anchor" href="#五项描写-完整例句" aria-label="Permalink to &quot;五项描写：完整例句&quot;">​</a></h3><p><code>Liema aġġettivi tuża biex tiddeskrivi…?</code>＝你用哪些形容词描述……？<strong>Liema aġġettivi</strong> 哪些形容词，<strong>tuża</strong> 你用，<strong>biex tiddeskrivi</strong> 为了描述。</p><table tabindex="0"><thead><tr><th>对象与例句</th><th>中文与逐词／短语解析</th></tr></thead><tbody><tr><td>1. Kejk — Il-kejk taċ-ċikkulata huwa kbir, artab u ħelu, u fuq għandu frott aħmar frisk.</td><td>巧克力蛋糕大、松软、甜，上有新鲜红色水果。<br><strong>Il-kejk taċ-ċikkulata</strong>：巧克力蛋糕。<br><strong>huwa</strong>：是。<br><strong>kbir, artab u ħelu</strong>：大、软、甜，配阳性 kejk。<br><strong>u fuq għandu</strong>：并且它上面有。<br><strong>frott aħmar frisk</strong>：新鲜红色水果，frott 为集合词。</td></tr><tr><td>2. Tuffieħa — Din it-tuffieħa ħamra hija friska u mmerqa, għalhekk se niekolha wara l-ikla.</td><td>这红苹果新鲜多汁，所以饭后要吃它。<br><strong>Din it-tuffieħa ħamra</strong>：这个红苹果，阴性。<br><strong>hija friska u mmerqa</strong>：新鲜而多汁。<br><strong>għalhekk</strong>：因此。<br><strong>se niekolha</strong>：我将吃它，-ha。<br><strong>wara l-ikla</strong>：饭后。</td></tr><tr><td>3. Pajjiż — Dan il-pajjiż huwa żgħir iżda sabiħ, u għandu bliet antiki u kampanja ħadra.</td><td>这个国家小而美，有古城和绿色乡野。<br><strong>Dan il-pajjiż</strong>：这个国家，阳性。<br><strong>huwa żgħir iżda sabiħ</strong>：小但美丽。<br><strong>u għandu</strong>：并有。<br><strong>bliet antiki</strong>：古老城市。<br><strong>u kampanja ħadra</strong>：与绿色乡野，ħadra 配 kampanja。</td></tr><tr><td>4. Vaganza — Il-vaganza tagħna kienet twila u interessanti, iżda xi ġranet kienu ta’ għeja minħabba l-mixi.</td><td>假期长且有趣，但一些日子因走路而累人。<br><strong>Il-vaganza tagħna</strong>：我们的假期，阴性。<br><strong>kienet twila u interessanti</strong>：长而有趣。<br><strong>iżda xi ġranet</strong>：但某些日子。<br><strong>kienu ta’ għeja</strong>：很累人，字面“是疲劳的日子”。<br><strong>minħabba l-mixi</strong>：因为步行。</td></tr><tr><td>5. Ħabiba tiegħek — Il-ħabiba tiegħi hija ġentili, intelliġenti u paċenzjuża, u dejjem tgħinni meta jkolli problema.</td><td>我的女性朋友温柔、聪明、有耐心，有问题总帮我。<br><strong>Il-ħabiba tiegħi</strong>：我的女性朋友。<br><strong>hija ġentili</strong>：她友善。<br><strong>intelliġenti</strong>：聪明。<br><strong>u paċenzjuża</strong>：并有耐心，阴性。<br><strong>u dejjem tgħinni</strong>：并总帮助我。<br><strong>meta jkolli problema</strong>：当我有问题。</td></tr></tbody></table><hr><h2 id="_9-十六个复数与分类" tabindex="-1">9 十六个复数与分类 <a class="header-anchor" href="#_9-十六个复数与分类" aria-label="Permalink to &quot;9 十六个复数与分类&quot;">​</a></h2><h3 id="十六个复数与分类" tabindex="-1">十六个复数与分类 <a class="header-anchor" href="#十六个复数与分类" aria-label="Permalink to &quot;十六个复数与分类&quot;">​</a></h3><p><code>Il-Plural sħiħ u miksur – Agħti l-plural ta’ dawn in-nomi mbagħad ikteb hux sħiħ jew miksur</code>＝给出这些名词的复数，再写是完整复数还是破碎复数。</p><p><strong>Il-plural</strong>：复数。<br><strong>sħiħ</strong>：完整，语法上指主要靠词尾构成的复数。<br><strong>miksur</strong>：破碎，主要靠词内部结构变化。<br><strong>Agħti</strong>：给出。<br><strong>ta’ dawn in-nomi</strong>：这些名词的。<br><strong>mbagħad ikteb</strong>：随后写。<br><strong>hux … jew …</strong>：是否……还是……。</p><table tabindex="0"><thead><tr><th>编号</th><th>单数 → 复数</th><th>分类</th><th>中文与构形提示</th></tr></thead><tbody><tr><td>1</td><td>lapes → lapsijiet</td><td>sħiħ</td><td>铅笔；-ijiet，词干也略有调整</td></tr><tr><td>2</td><td>tazza → tazzi</td><td>sħiħ</td><td>杯子；末尾 a → i</td></tr><tr><td>3</td><td>raġel → rġiel</td><td>miksur</td><td>男人；词干内部元音及结构改变</td></tr><tr><td>4</td><td>saqqu → saqqijiet</td><td>sħiħ</td><td>床垫；-ijiet</td></tr><tr><td>5</td><td>karozza → karozzi</td><td>sħiħ</td><td>汽车；末尾 i</td></tr><tr><td>6</td><td>ajruplan → ajruplani</td><td>sħiħ</td><td>飞机；末尾 i</td></tr><tr><td>7</td><td>mejda → imwejjed</td><td>miksur</td><td>桌子；也可遇到 mwejjed 形式，注意双写 j</td></tr><tr><td>8</td><td>dar → djar</td><td>miksur</td><td>房子；内部结构变化</td></tr><tr><td>9</td><td>kċina → kċejjen</td><td>miksur</td><td>厨房；内部元音变化</td></tr><tr><td>10</td><td>ikla → ikliet</td><td>sħiħ</td><td>餐；-iet</td></tr><tr><td>11</td><td>dgħajsa → dgħajjes</td><td>miksur</td><td>小船；内部词形变化</td></tr><tr><td>12</td><td>siġra → siġar</td><td>miksur</td><td>树；常用复数 siġar；计数形式 siġriet 也是完整复数，须区别</td></tr><tr><td>13</td><td>furketta → frieket</td><td>miksur</td><td>叉子；内部词形变化</td></tr><tr><td>14</td><td>stilla → stilel</td><td>miksur</td><td>星星；内部词形变化</td></tr><tr><td>15</td><td>xogħol → xogħlijiet</td><td>sħiħ</td><td>工作、作品、工程；-ijiet</td></tr><tr><td>16</td><td>xahar → xhur</td><td>miksur</td><td>月份；内部元音变化</td></tr></tbody></table><p>“完整复数”不等于“原词绝不改变，只在末尾粘一个字母”；例如 <strong>lapes → lapsijiet</strong> 有词干调整，但仍按后缀构词分类。某些名词有不同语义或计数条件下的多个复数，不能把本表当作排他词典。</p><hr><h2 id="_10-复数分栏与数词介词十题" tabindex="-1">10 复数分栏与数词介词十题 <a class="header-anchor" href="#_10-复数分栏与数词介词十题" aria-label="Permalink to &quot;10 复数分栏与数词介词十题&quot;">​</a></h2><h3 id="第一题-复数分栏" tabindex="-1">第一题：复数分栏 <a class="header-anchor" href="#第一题-复数分栏" aria-label="Permalink to &quot;第一题：复数分栏&quot;">​</a></h3><p><code>Issepara l-kliem f’kolonni differenti skont jiġux iffurmati fil-plural permezz ta’ suffiss jew inkella permezz ta’ bidla interna. Fil-kolonni ikteb biss il-kelma fil-plural.</code></p><p>译：根据复数是通过后缀还是内部变化形成，将词分栏；栏里只写复数。</p><p><strong>Issepara</strong>：分开。<br><strong>l-kliem</strong>：词语。<br><strong>f’kolonni differenti</strong>：在不同栏内。<br><strong>skont</strong>：根据。<br><strong>jiġux iffurmati</strong>：是否被构成。<br><strong>fil-plural</strong>：复数形式。<br><strong>permezz ta’ suffiss</strong>：通过后缀。<br><strong>jew inkella</strong>：或者。<br><strong>permezz ta’ bidla interna</strong>：通过内部变化。<br><strong>Fil-kolonni</strong>：在栏内。<br><strong>ikteb biss</strong>：只写。<br><strong>il-kelma fil-plural</strong>：复数词。</p><table tabindex="0"><thead><tr><th>完整复数：只填这些词</th><th>破碎复数：只填这些词</th></tr></thead><tbody><tr><td>fletts<br>muntanji<br>roti<br>vaski<br>laptops<br>pumijiet<br>lasti<br>ġebliet</td><td>rġiel<br>btieħi<br>klieb<br>ibħra<br>ħnieżer<br>xbieki<br>subien</td></tr></tbody></table><p><strong>widnejn</strong> 另列：widna（耳朵）→ widnejn（双耳／耳朵），历史双数／成对形式，不能完全用题目的二分覆盖。若教师将 -ejn 形式并入后缀类，应遵从课堂标注，同时保留这个语法区别，不将它说成典型破碎复数。</p><table tabindex="0"><thead><tr><th>原文词对</th><th>中文与解析</th></tr></thead><tbody><tr><td>raġel – rġiel</td><td>男人，单数／复数</td></tr><tr><td>flett – fletts</td><td>公寓，英语式 -s 后缀</td></tr><tr><td>muntanja – muntanji</td><td>山，末尾变化为 i</td></tr><tr><td>bitħa – btieħi</td><td>院子，内部变化</td></tr><tr><td>kelb – klieb</td><td>狗，内部变化</td></tr><tr><td>rota – roti</td><td>自行车，末尾 i</td></tr><tr><td>baħar – ibħra</td><td>海，内部变化</td></tr><tr><td>ħanżir – ħnieżer</td><td>猪，内部变化</td></tr><tr><td>vaska – vaski</td><td>浴盆／水槽，末尾 i</td></tr><tr><td>xibka – xbieki</td><td>网，内部变化</td></tr><tr><td>widna – widnejn</td><td>耳朵／双耳，历史双数</td></tr><tr><td>laptop – laptops</td><td>笔记本电脑，-s</td></tr><tr><td>tifel – subien</td><td>男孩／男孩们，subien 特指男孩；tifel 表“儿童”时常见复数 tfal</td></tr><tr><td>pum – pumijiet</td><td>把手、旋钮，-ijiet</td></tr><tr><td>lasta – lasti</td><td>杆，末尾 i</td></tr><tr><td>ġebla – ġebliet</td><td>石块，-iet；与集合词 ġebel 区别</td></tr></tbody></table><h3 id="第二题-数词与介词十题" tabindex="-1">第二题：数词与介词十题 <a class="header-anchor" href="#第二题-数词与介词十题" aria-label="Permalink to &quot;第二题：数词与介词十题&quot;">​</a></h3><p><code>In-Numri u l-Prepożizzjonijiet – Imla l-vojt</code>＝数词和介词——填空。<strong>In-numri</strong> 数字，<strong>il-prepożizzjonijiet</strong> 介词。没有位置图或完整语境，空间介词不是唯一答案；下列构成一组通顺例句。</p><table tabindex="0"><thead><tr><th>完整参考句</th><th>中文与逐词／短语解析</th></tr></thead><tbody><tr><td>1. <strong>Fuq</strong> l-iskrivanija għandi <strong>żewġ</strong> kotba, <strong>tliet</strong> lapsijiet u <strong>ħames</strong> fajls.</td><td>我桌上有两本书、三支铅笔和五个档案夹。<br><strong>Fuq l-iskrivanija</strong>：在书桌上。<br><strong>għandi</strong>：我有。<br><strong>żewġ kotba</strong>：两本书。<br><strong>tliet lapsijiet</strong>：三支铅笔。<br><strong>u ħames fajls</strong>：和五个文件夹。</td></tr><tr><td>2. Il-qattus raqad <strong>fuq</strong> is-sodda, <strong>b’erba’</strong> kutri fuqu.</td><td>猫睡在床上，身上盖着四条毯子。<br><strong>Il-qattus</strong>：猫。<br><strong>raqad</strong>：睡了。<br><strong>fuq is-sodda</strong>：在床上。<br><strong>b’erba’ kutri</strong>：有四条毯子。<br><strong>fuqu</strong>：在它上面，fuq + u。</td></tr><tr><td>3. <strong>Quddiem</strong> id-dar hemm <strong>seba’</strong> siġriet.</td><td>房前有七棵树。<br><strong>Quddiem</strong>：在前面；也可按其他情境选 ħdejn 旁边。<br><strong>id-dar</strong>：房子。<br><strong>hemm</strong>：有。<br><strong>seba’ siġriet</strong>：七棵树，计数复数。</td></tr><tr><td>4. <strong>Ħdejn il-knisja</strong> fetħu <strong>sitt</strong> iħwienet ġodda.</td><td>教堂旁新开六家店。<br><strong>Ħdejn il-knisja</strong>：教堂旁；原题 l-knisja 与所选介词连用时补为 il-knisja。<br><strong>fetħu</strong>：他们开了／开业了。<br><strong>sitt iħwienet</strong>：六家商店。<br><strong>ġodda</strong>：新的，复数。</td></tr><tr><td>5. <strong>Għoxrin</strong> student applikaw għall-kors.</td><td>二十名学生申请了课程。<br><strong>Għoxrin student</strong>：二十名学生，数词后 student 为单数形式。<br><strong>applikaw</strong>：他们申请了，谓语表复数。<br><strong>għall-kors</strong>：这个课程。</td></tr><tr><td>6. <strong>Fuq</strong> l-ajruplan konna <strong>tmenin</strong> ruħ.</td><td>飞机上我们共八十人。<br><strong>Fuq l-ajruplan</strong>：在飞机上，也可 ġewwa l-ajruplan。<br><strong>konna</strong>：我们当时是。<br><strong>tmenin</strong>：八十。<br><strong>ruħ</strong>：人／人头，在计人数时使用，不直译灵魂。</td></tr><tr><td>7. <strong>Iż-żewġt</strong> itfal staħbew <strong>wara</strong> il-purtieri.</td><td>两个孩子藏在窗帘后面。<br><strong>Iż-żewġt itfal</strong>：这两个孩子；元音起首名词前用 żewġt。<br><strong>staħbew</strong>：他们躲藏了。<br><strong>wara</strong>：后面。<br><strong>il-purtieri</strong>：窗帘。</td></tr><tr><td>8. Il-ħanut tal-merċa jinsab <strong>bejn</strong> tal-laħam u tal-ħwejjeġ.</td><td>杂货店位于肉店与服装店之间。<br><strong>Il-ħanut tal-merċa</strong>：杂货店。<br><strong>jinsab</strong>：位于。<br><strong>bejn</strong>：之间。<br><strong>tal-laħam</strong>：卖肉的，省略 il-ħanut。<br><strong>u tal-ħwejjeġ</strong>：和卖衣服的。</td></tr><tr><td>9. Daħħal il-kejk <strong>fil-forn</strong> u agħmel it-temperatura fuq <strong>mija u ħamsa u sebgħin</strong> gradi <strong>Celsius</strong>.</td><td>把蛋糕放进烤箱，温度设为 175 摄氏度。<br><strong>Daħħal</strong>：放入，命令。<br><strong>il-kejk</strong>：蛋糕。<br><strong>fil-forn</strong>：在／进烤箱，fi + 定冠词。<br><strong>u agħmel</strong>：并设置。<br><strong>it-temperatura fuq</strong>：温度在……。<br><strong>mija u ħamsa u sebgħin</strong>：175，字面一百和五和七十。<br><strong>gradi Celsius</strong>：摄氏度；原文 celcius 拼写另行修正。</td></tr><tr><td>10. Il-basket l-iswed jiswa <strong>ħamsa u ħamsin</strong> ewro.</td><td>黑包售价 55 欧元。<br><strong>Il-basket l-iswed</strong>：黑色包，定冠词在名词、形容词上重复。<br><strong>jiswa</strong>：价值／售价。<br><strong>ħamsa u ħamsin</strong>：55，五和五十。<br><strong>ewro</strong>：欧元。</td></tr></tbody></table><hr><h2 id="_11-十二个月造句" tabindex="-1">11 十二个月造句 <a class="header-anchor" href="#_11-十二个月造句" aria-label="Permalink to &quot;11 十二个月造句&quot;">​</a></h2><h3 id="十二个月-每月一个较完整例句" tabindex="-1">十二个月：每月一个较完整例句 <a class="header-anchor" href="#十二个月-每月一个较完整例句" aria-label="Permalink to &quot;十二个月：每月一个较完整例句&quot;">​</a></h3><p><code>Ix-Xhur – Ikteb sentenza dwar kull xahar</code>＝月份——就每个月写一句。<strong>Ix-xhur</strong> 月份复数，<strong>Ikteb sentenza</strong> 写句子，<strong>dwar kull xahar</strong> 关于每个月。以下是示范生活安排，天气不是对每年每月的保证。</p><table tabindex="0"><thead><tr><th>月份与例句</th><th>中文与逐词／短语解析</th></tr></thead><tbody><tr><td>1. <strong>Jannar</strong> — F’Jannar nibda sena ġdida billi nagħmel pjan għall-istudju u nipprova nqatta’ aktar ħin mal-familja.</td><td>一月开始新一年，制定学习计划，多陪家人。<br><strong>F’Jannar</strong>：在一月。<br><strong>nibda sena ġdida</strong>：我开始新一年。<br><strong>billi nagħmel pjan</strong>：通过制定计划。<br><strong>għall-istudju</strong>：用于学习。<br><strong>u nipprova</strong>：并尝试。<br><strong>nqatta’ aktar ħin</strong>：花更多时间。<br><strong>mal-familja</strong>：与家人。</td></tr><tr><td>2. <strong>Frar</strong> — Fi Frar, meta jkun il-bard, inħobb insajjar soppa sħuna u naqra ktieb tajjeb id-dar.</td><td>二月天冷时爱煮热汤，在家读好书。<br><strong>Fi Frar</strong>：在二月。<br><strong>meta jkun il-bard</strong>：当天气寒冷。<br><strong>inħobb insajjar</strong>：我喜欢做。<br><strong>soppa sħuna</strong>：热汤。<br><strong>u naqra ktieb tajjeb</strong>：并读好书。<br><strong>id-dar</strong>：在家。</td></tr><tr><td>3. <strong>Marzu</strong> — F’Marzu nimxi fil-kampanja ma’ sħabi u nieħu ritratti tal-fjuri li jibdew jidhru matul ir-rebbiegħa.</td><td>三月和朋友乡间步行，拍春季初开的花。<br><strong>F’Marzu</strong>：在三月。<br><strong>nimxi fil-kampanja</strong>：我在乡间走。<br><strong>ma’ sħabi</strong>：和朋友。<br><strong>u nieħu ritratti</strong>：并拍照。<br><strong>tal-fjuri</strong>：花的。<br><strong>li jibdew jidhru</strong>：开始出现的。<br><strong>matul ir-rebbiegħa</strong>：春季期间。</td></tr><tr><td>4. <strong>April</strong> — F’April nixtieq nieħu ftit jiem vaganza biex inżur belt ġdida u nitgħallem aktar dwar l-istorja tagħha.</td><td>四月想休几天，参观新城市、了解历史。<br><strong>F’April</strong>：在四月。<br><strong>nixtieq nieħu</strong>：我想休／拿。<br><strong>ftit jiem vaganza</strong>：几天假。<br><strong>biex inżur</strong>：为了参观。<br><strong>belt ġdida</strong>：新城市，阴性。<br><strong>u nitgħallem aktar</strong>：并学更多。<br><strong>dwar l-istorja tagħha</strong>：关于它的历史。</td></tr><tr><td>5. <strong>Mejju</strong> — F’Mejju normalment nistudja aktar filgħaxija għax irrid inkun ippreparat għall-eżamijiet li jkolli fl-aħħar tal-kors.</td><td>五月晚上通常多学习，准备课程末考试。<br><strong>F’Mejju</strong>：在五月。<br><strong>normalment nistudja aktar</strong>：通常我更多学习。<br><strong>filgħaxija</strong>：晚上。<br><strong>għax irrid inkun ippreparat</strong>：因为想准备好，男性；女性 ippreparata。<br><strong>għall-eżamijiet</strong>：为考试。<br><strong>li jkolli</strong>：我会有的。<br><strong>fl-aħħar tal-kors</strong>：课程结束时。</td></tr><tr><td>6. <strong>Ġunju</strong> — F’Ġunju l-ġranet ikunu twal, u wara x-xogħol kultant immur il-baħar biex ngħum u nistrieħ.</td><td>六月白昼长，下班有时去海边游泳休息。<br><strong>F’Ġunju</strong>：在六月。<br><strong>l-ġranet ikunu twal</strong>：白天通常很长。<br><strong>u wara x-xogħol</strong>：并在下班后。<br><strong>kultant immur il-baħar</strong>：有时去海边。<br><strong>biex ngħum u nistrieħ</strong>：为了游泳与休息。</td></tr><tr><td>7. <strong>Lulju</strong> — F’Lulju nippreferi noħroġ kmieni filgħodu, nieħu l-ilma miegħi u nevita mixjiet twal fix-xemx ta’ nofsinhar.</td><td>七月宁愿早出门，随身带水，避免午间暴晒长走。<br><strong>F’Lulju</strong>：在七月。<br><strong>nippreferi noħroġ</strong>：我更喜欢出门。<br><strong>kmieni filgħodu</strong>：一大早。<br><strong>nieħu l-ilma miegħi</strong>：随身带水。<br><strong>u nevita</strong>：并避免。<br><strong>mixjiet twal</strong>：长距离步行。<br><strong>fix-xemx ta’ nofsinhar</strong>：在中午太阳下。</td></tr><tr><td>8. <strong>Awwissu</strong> — F’Awwissu nqatta’ aktar ħin mal-ħbieb ħdejn il-baħar u nħobb niekol xi ħaġa ħafifa wara l-għawm.</td><td>八月多与朋友在海边，游泳后爱吃清淡食物。<br><strong>F’Awwissu</strong>：在八月。<br><strong>nqatta’ aktar ħin</strong>：我花更多时间。<br><strong>mal-ħbieb</strong>：与朋友。<br><strong>ħdejn il-baħar</strong>：海边。<br><strong>u nħobb niekol</strong>：并喜欢吃。<br><strong>xi ħaġa ħafifa</strong>：一些清淡食物。<br><strong>wara l-għawm</strong>：游泳之后。</td></tr><tr><td>9. <strong>Settembru</strong> — F’Settembru nerġa’ nibda l-kors tal-Malti u nirrevedi n-noti tiegħi biex niftakar dak li tgħallimt qabel is-sajf.</td><td>九月重新上马耳他语课，复习笔记记起暑前所学。<br><strong>F’Settembru</strong>：在九月。<br><strong>nerġa’ nibda</strong>：我重新开始。<br><strong>l-kors tal-Malti</strong>：马耳他语课程。<br><strong>u nirrevedi n-noti tiegħi</strong>：并复习笔记。<br><strong>biex niftakar</strong>：为了记起。<br><strong>dak li tgħallimt</strong>：我学过的内容。<br><strong>qabel is-sajf</strong>：夏季之前。</td></tr><tr><td>10. <strong>Ottubru</strong> — F’Ottubru nħobb inżur mużew ma’ ħabib u wara noqogħdu f’kafetterija nitkellmu dwar dak li rajna.</td><td>十月喜欢与朋友逛博物馆，之后在咖啡馆聊所见。<br><strong>F’Ottubru</strong>：在十月。<br><strong>nħobb inżur mużew</strong>：我喜欢参观博物馆。<br><strong>ma’ ħabib</strong>：和朋友。<br><strong>u wara</strong>：然后。<br><strong>noqogħdu f’kafetterija</strong>：我们待在咖啡馆。<br><strong>nitkellmu dwar</strong>：谈论。<br><strong>dak li rajna</strong>：我们所看到的。</td></tr><tr><td>11. <strong>Novembru</strong> — F’Novembru, jekk tkun ix-xita, nibqa’ d-dar u nuża l-ħin biex nistudja, insajjar u nċempel lill-familja.</td><td>十一月下雨时留家，学习、做饭、给家人打电话。<br><strong>F’Novembru</strong>：在十一月。<br><strong>jekk tkun ix-xita</strong>：如果下雨。<br><strong>nibqa’ d-dar</strong>：我留在家。<br><strong>u nuża l-ħin</strong>：并利用时间。<br><strong>biex nistudja</strong>：为了学习。<br><strong>insajjar</strong>：做饭。<br><strong>u nċempel lill-familja</strong>：并给家人打电话。</td></tr><tr><td>12. <strong>Diċembru</strong> — F’Diċembru niltaqa’ mal-familja għall-festi, ngħin fit-tisjir u nħejji rigali żgħar għall-persuni li nħobb.</td><td>十二月与家人过节，帮做饭，为所爱之人备小礼物。<br><strong>F’Diċembru</strong>：在十二月。<br><strong>niltaqa’ mal-familja</strong>：我见家人。<br><strong>għall-festi</strong>：为节庆。<br><strong>ngħin fit-tisjir</strong>：帮忙做饭。<br><strong>u nħejji</strong>：并准备。<br><strong>rigali żgħar</strong>：小礼物。<br><strong>għall-persuni li nħobb</strong>：给我爱的人们。</td></tr></tbody></table><hr><h2 id="_12-八幅职业图片与例句" tabindex="-1">12 八幅职业图片与例句 <a class="header-anchor" href="#_12-八幅职业图片与例句" aria-label="Permalink to &quot;12 八幅职业图片与例句&quot;">​</a></h2><h3 id="八幅职业图片与例句" tabindex="-1">八幅职业图片与例句 <a class="header-anchor" href="#八幅职业图片与例句" aria-label="Permalink to &quot;八幅职业图片与例句&quot;">​</a></h3><p><code>L-impjiegi</code>＝工作／职业。<code>Ikteb il-professjoni ta’ dawn il-persuni taħt l-istampa</code>＝在图下写出这些人的职业。<strong>Ikteb</strong> 写，<strong>il-professjoni</strong> 职业，<strong>ta’ dawn il-persuni</strong> 这些人的，<strong>taħt l-istampa</strong> 在图片下方。英语 <code>Write down the profession of these persons under their picture</code> 与此同义。</p><p>图片按从上到下、每行从左到右排列；右上角另有办公照片，不另计填词框。图片无法证明人物的真实身份，以下根据明显工具及情境作答。</p><table tabindex="0"><thead><tr><th>编号、职业与完整例句</th><th>中文与逐词／短语解析</th></tr></thead><tbody><tr><td>1. <strong>tabib</strong> — It-tabib jara lill-pazjenti fil-klinika u jispjegalhom kif għandhom jieħdu l-mediċina tagħhom.</td><td>医生在诊所看病人，解释如何服药。<br><strong>It-tabib</strong>：男医生；女医生 tabiba。<br><strong>jara lill-pazjenti</strong>：看诊病人们。<br><strong>fil-klinika</strong>：在诊所。<br><strong>u jispjegalhom</strong>：并向他们说明。<br><strong>kif għandhom jieħdu</strong>：应该如何服用。<br><strong>l-mediċina tagħhom</strong>：他们的药。</td></tr><tr><td>2. <strong>ħaddiema tat-tindif</strong> — Il-ħaddiema tat-tindif tnaddaf l-art u l-kmamar biex l-uffiċċju jkun nadif qabel jaslu l-impjegati.</td><td>女清洁工打扫地板、房间，让员工到达前办公室干净。<br><strong>Il-ħaddiema tat-tindif</strong>：女清洁工；同形也能指复数，本句由 tnaddaf 定为女单数。<br><strong>tnaddaf l-art u l-kmamar</strong>：她清洁地板和房间。<br><strong>biex l-uffiċċju jkun nadif</strong>：让办公室干净。<br><strong>qabel jaslu l-impjegati</strong>：员工到来之前。<br><strong>可接受称法</strong>：若意指家庭佣人可说 seftura，但图片不足以确定雇佣性质。</td></tr><tr><td>3. <strong>għalliem</strong> — L-għalliem jispjega l-lezzjoni fuq il-bord u jagħti eżempji biex it-tfal jifhmu aħjar.</td><td>老师在板上讲课举例，帮助儿童理解。<br><strong>L-għalliem</strong>：男老师；女老师 għalliema。<br><strong>jispjega l-lezzjoni</strong>：讲解课程。<br><strong>fuq il-bord</strong>：在板上。<br><strong>u jagħti eżempji</strong>：并给例子。<br><strong>biex it-tfal</strong>：为了让儿童。<br><strong>jifhmu aħjar</strong>：理解得更好。</td></tr><tr><td>4. <strong>pittur</strong> — Il-pittur juża ħafna kuluri biex ipinġi veduta tal-baħar li se juriha f’wirja.</td><td>画家用多种颜色画海景，准备展出。<br><strong>Il-pittur</strong>：男画家；女画家 pittriċi。<br><strong>juża ħafna kuluri</strong>：用很多颜色。<br><strong>biex ipinġi</strong>：为了画。<br><strong>veduta tal-baħar</strong>：海景。<br><strong>li se juriha</strong>：将展示它，-ha。<br><strong>f’wirja</strong>：在展览中。</td></tr><tr><td>5. <strong>bejjiegħa tal-ġelat</strong> — Il-bejjiegħa tal-ġelat isservi lit-tfal fil-pjazza u tistaqsihom liema togħma jippreferu.</td><td>女冰淇淋售卖者在广场服务儿童，问喜欢什么口味。<br><strong>Il-bejjiegħa tal-ġelat</strong>：女冰淇淋售卖者。<br><strong>isservi lit-tfal</strong>：为儿童服务。<br><strong>fil-pjazza</strong>：广场上。<br><strong>u tistaqsihom</strong>：并问他们。<br><strong>liema togħma jippreferu</strong>：更喜欢哪种口味。<br><strong>别称</strong>：ġelatiera 也可用于此职业；此处用描述性称法避免图片歧义。</td></tr><tr><td>6. <strong>kantanta</strong> — Il-kantanta tkanta fuq il-palk ma’ grupp ta’ mużiċisti waqt kunċert għall-familji.</td><td>女歌手在家庭音乐会与乐手同台唱歌。<br><strong>Il-kantanta</strong>：女歌手；男性 kantant。<br><strong>tkanta</strong>：她唱歌。<br><strong>fuq il-palk</strong>：舞台上。<br><strong>ma’ grupp ta’ mużiċisti</strong>：与一组乐手。<br><strong>waqt kunċert</strong>：音乐会期间。<br><strong>għall-familji</strong>：面向家庭。</td></tr><tr><td>7. <strong>bidwi</strong> — Il-bidwi jaħdem fl-għalqa kmieni filgħodu u jkabbar ħaxix frisk biex ibigħu fis-suq.</td><td>农民清晨在田里劳动，种新鲜蔬菜出售。<br><strong>Il-bidwi</strong>：男农民；女性 bidwija。<br><strong>jaħdem fl-għalqa</strong>：在田里工作。<br><strong>kmieni filgħodu</strong>：清晨。<br><strong>u jkabbar ħaxix frisk</strong>：并种新鲜蔬菜。<br><strong>biex ibigħu</strong>：为了卖它，-u 指集合名词 ħaxix。<br><strong>fis-suq</strong>：在市场。</td></tr><tr><td>8. <strong>attur</strong> — L-attur jitgħallem il-kliem tiegħu u jipprattika ma’ sħabu qabel l-ispettaklu fit-teatru.</td><td>演员记台词，演出前与同伴排练。<br><strong>L-attur</strong>：男演员；女演员 attriċi。<br><strong>jitgħallem il-kliem tiegħu</strong>：学习他的台词。<br><strong>u jipprattika</strong>：并练习。<br><strong>ma’ sħabu</strong>：与同伴。<br><strong>qabel l-ispettaklu</strong>：演出前。<br><strong>fit-teatru</strong>：在剧院。</td></tr></tbody></table><hr><h2 id="_13-职业填字-十题" tabindex="-1">13 职业填字：十题 <a class="header-anchor" href="#_13-职业填字-十题" aria-label="Permalink to &quot;13 职业填字：十题&quot;">​</a></h2><h3 id="职业填字-十题" tabindex="-1">职业填字：十题 <a class="header-anchor" href="#职业填字-十题" aria-label="Permalink to &quot;职业填字：十题&quot;">​</a></h3><p><code>It-tisliba dwar l-impjiegi</code>＝关于职业的填字游戏。<strong>it-tisliba</strong> 填字，<strong>dwar</strong> 关于，<strong>l-impjiegi</strong> 职业。</p><p>以下长度按书写字母逐个计，本组答案无 għ 的双字母计格问题。依图：1、2、3、4、7、9 向下；5、6、8、10 向右；3 和 6 共享起点 b。</p><table tabindex="0"><thead><tr><th>题号与完整线索</th><th>答案、中文与逐词／短语解析</th></tr></thead><tbody><tr><td>1. Jien insajjar fil-kċina. / I cook in the kitchen.</td><td><strong>kok</strong>，3 字母，厨师。<br><strong>Jien</strong>：我。<br><strong>insajjar</strong>：我做饭。<br><strong>fil-kċina</strong>：在厨房。</td></tr><tr><td>2. Jien nagħti l-injezzjonijiet u l-pilloli lill-pazjenti. / I give injections and pills to patients.</td><td><strong>ners</strong>，4 字母，护士。<br><strong>Jien nagħti</strong>：我给予。<br><strong>l-injezzjonijiet</strong>：针剂／注射。<br><strong>u l-pilloli</strong>：和药片。<br><strong>lill-pazjenti</strong>：给病人们。<br><strong>辨析</strong>：tabib 也可能做部分这些事，但 5 字母不合此格。</td></tr><tr><td>3. Jien nibni d-djar. / I build houses.</td><td><strong>bennej</strong>，6 字母，建筑工／泥瓦匠。<br><strong>Jien</strong>：我。<br><strong>nibni</strong>：我建造。<br><strong>d-djar</strong>：房子们。</td></tr><tr><td>4. Jien inżomm l-ordni fis-soċjetà. / I maintain order in society.</td><td><strong>pulizija</strong>，8 字母，警察。<br><strong>Jien inżomm</strong>：我维持。<br><strong>l-ordni</strong>：秩序。<br><strong>fis-soċjetà</strong>：在社会中。</td></tr><tr><td>5. Jien nassigura li l-pajjiż huwa protett u sigur. / I ensure the protection and safety of a country.</td><td><strong>suldat</strong>，6 字母，军人。<br><strong>Jien nassigura</strong>：我确保。<br><strong>li</strong>：……这件事。<br><strong>l-pajjiż</strong>：国家。<br><strong>huwa protett</strong>：受到保护。<br><strong>u sigur</strong>：并安全。</td></tr><tr><td>6. Jien insuq l-ajruplani. / I drive airplanes.</td><td><strong>bdot</strong>，4 字母，飞行员。<br><strong>Jien insuq</strong>：我驾驶。<br><strong>l-ajruplani</strong>：飞机们。<br><strong>辨析</strong>：pilota 是同义职业词，但长度不同；本格与 bennej 共享 b。</td></tr><tr><td>7. Jien inqassam l-ittri d-dar. / I post letters in houses.</td><td><strong>pustier</strong>，7 字母，邮递员。<br><strong>Jien inqassam</strong>：我分发。<br><strong>l-ittri</strong>：信件。<br><strong>d-dar</strong>：到家里，依原题省略式表达。</td></tr><tr><td>8. Jien nibni l-għamara bl-injam. / I build furniture using wood.</td><td><strong>mastrudaxxa</strong>，11 字母，木匠。<br><strong>Jien nibni</strong>：我建造／制作。<br><strong>l-għamara</strong>：家具。<br><strong>bl-injam</strong>：用木材，bi + 定冠词。</td></tr><tr><td>9. Jien niddefendi n-nies fil-qorti. / I defend people in court.</td><td><strong>avukat</strong>，6 字母，律师。<br><strong>Jien niddefendi</strong>：我辩护。<br><strong>n-nies</strong>：人们。<br><strong>fil-qorti</strong>：法庭里。</td></tr><tr><td>10. Jien norganizza l-appuntament u l-karti ta’ persuni importanti. / I organise appointments and papers for people.</td><td><strong>segretarju</strong>，10 字母，秘书。<br><strong>Jien norganizza</strong>：我安排整理。<br><strong>l-appuntament</strong>：预约，原马耳他语为单数；英语线索用复数 appointments。<br><strong>u l-karti</strong>：与文件。<br><strong>ta’ persuni importanti</strong>：重要人士的；英文线索较简略。</td></tr></tbody></table><hr><h2 id="_14-sara-的日记与叙事顺序" tabindex="-1">14 Sara 的日记与叙事顺序 <a class="header-anchor" href="#_14-sara-的日记与叙事顺序" aria-label="Permalink to &quot;14 Sara 的日记与叙事顺序&quot;">​</a></h2><h3 id="sara-的日记-全文逐句解析" tabindex="-1">Sara 的日记：全文逐句解析 <a class="header-anchor" href="#sara-的日记-全文逐句解析" aria-label="Permalink to &quot;Sara 的日记：全文逐句解析&quot;">​</a></h3><p><code>Il-Qari – Aqra din is-silta u wieġeb il-mistoqsijiet</code>＝阅读——读本文并回答问题。<strong>Aqra</strong> 读，<strong>din is-silta</strong> 本文，<strong>u wieġeb</strong> 并回答，<strong>il-mistoqsijiet</strong> 问题。<code>Id-djarju ta’ Sara</code>＝Sara 的日记；<strong>id-djarju</strong> 日记，<strong>ta’ Sara</strong> Sara 的。</p><table tabindex="0"><thead><tr><th>原句</th><th>中文与逐词／短语解析</th></tr></thead><tbody><tr><td>Nhar il-Ħadd li għadda ħriġt mal-familja tiegħi.</td><td>上个星期天我和家人出去了。<br><strong>Nhar il-Ħadd</strong>：在星期天。<br><strong>li għadda</strong>：过去的。<br><strong>ħriġt</strong>：我出门了。<br><strong>mal-familja tiegħi</strong>：与我的家人。</td></tr><tr><td>Kienet xemx tisreġ u ħafna sħana, għalhekk ilbist libsa ħafifa u żanżant sandli ġdid.</td><td>太阳火辣、天气炎热，因此我穿轻薄连衣裙，第一次穿上新凉鞋。<br><strong>Kienet</strong>：当时有／是。<br><strong>xemx tisreġ</strong>：炽热的太阳，固定描写。<br><strong>u ħafna sħana</strong>：与很大的热度。<br><strong>għalhekk</strong>：所以。<br><strong>ilbist</strong>：我穿了。<br><strong>libsa ħafifa</strong>：轻薄连衣裙。<br><strong>u żanżant</strong>：并初次穿用新物，不只“买了”。<br><strong>sandli ġdid</strong>：新凉鞋，保留教材用法。</td></tr><tr><td>Oħti libset flokk abjad bil-komma qasira u qalziet blu.</td><td>姐妹穿白短袖上衣和蓝裤子。<br><strong>Oħti</strong>：我的姐妹。<br><strong>libset</strong>：她穿了。<br><strong>flokk abjad</strong>：白色上衣。<br><strong>bil-komma qasira</strong>：短袖的。<br><strong>u qalziet blu</strong>：和蓝裤子。</td></tr><tr><td>Ommi libset blaws roża u dublett iswed sal-irkoppa.</td><td>母亲穿粉红衬衫和黑色及膝裙。<br><strong>Ommi</strong>：我母亲。<br><strong>libset</strong>：她穿了。<br><strong>blaws roża</strong>：粉红女式衬衫。<br><strong>u dublett iswed</strong>：与黑裙。<br><strong>sal-irkoppa</strong>：到膝盖，sa + 定冠词。</td></tr><tr><td>Missieri libes qmis safra u qalziet iswed.</td><td>父亲穿黄衬衣、黑裤子。<br><strong>Missieri</strong>：我父亲。<br><strong>libes</strong>：他穿了。<br><strong>qmis safra</strong>：黄色衬衣，qmis 阴性。<br><strong>u qalziet iswed</strong>：和黑裤子，qalziet 在这里配阳性形容词。</td></tr><tr><td>Fl-għaxra ta’ filgħodu konna lesti u qbadna t-triq lejn iż-Żurrieq.</td><td>早上十点准备好，出发去 Żurrieq。<br><strong>Fl-għaxra ta’ filgħodu</strong>：上午十点。<br><strong>konna lesti</strong>：我们准备好了。<br><strong>u qbadna t-triq</strong>：并上路，字面“抓住道路”。<br><strong>lejn iż-Żurrieq</strong>：朝 Żurrieq，地名。</td></tr><tr><td>Hemm rajna veduta mill-isbaħ tal-baħar u l-wied, kif ukoll ta’ Filfla!</td><td>那里看见美丽海景、山谷，以及 Filfla 岛。<br><strong>Hemm</strong>：那里。<br><strong>rajna</strong>：我们看见。<br><strong>veduta mill-isbaħ</strong>：极美的景观。<br><strong>tal-baħar u l-wied</strong>：海与山谷的。<br><strong>kif ukoll</strong>：也包括。<br><strong>ta’ Filfla</strong>：Filfla 的景色，岛名。</td></tr><tr><td>Wara soqna lejn is-Siġġiewi u smajna quddies fil-knisja parrokkjali.</td><td>然后开去 Siġġiewi，在堂区教堂参加弥撒。<br><strong>Wara</strong>：之后。<br><strong>soqna</strong>：我们开车了。<br><strong>lejn is-Siġġiewi</strong>：朝 Siġġiewi。<br><strong>u smajna quddies</strong>：并参加弥撒，字面“听弥撒”。<br><strong>fil-knisja parrokkjali</strong>：堂区教堂里。</td></tr><tr><td>Wara l-quddies kien sar il-ħin għall-ikla ta’ nofsinhar u morna f’restorant Ħad-Dingli għall-veduta tal-irdum.</td><td>弥撒后到了午饭时间，去 Dingli 一家能欣赏悬崖景色的餐厅。<br><strong>Wara l-quddies</strong>：弥撒后。<br><strong>kien sar il-ħin</strong>：已到时间。<br><strong>għall-ikla ta’ nofsinhar</strong>：午餐的。<br><strong>u morna f’restorant</strong>：并去餐馆。<br><strong>Ħad-Dingli</strong>：在 Dingli。<br><strong>għall-veduta tal-irdum</strong>：为了悬崖景观。</td></tr><tr><td>Jien u oħti ordnajna platt għaġin biż-zalza ħamra u ommi u missieri ħadu biċċa laħam bil-patata.</td><td>我和姐妹点红酱意面，父母点肉配土豆。<br><strong>Jien u oħti</strong>：我和姐妹。<br><strong>ordnajna</strong>：我们点餐。<br><strong>platt għaġin</strong>：一盘意面。<br><strong>biż-zalza ħamra</strong>：配红酱。<br><strong>u ommi u missieri</strong>：而母亲、父亲。<br><strong>ħadu</strong>：他们要了／吃了。<br><strong>biċċa laħam</strong>：一块肉。<br><strong>bil-patata</strong>：配土豆。</td></tr><tr><td>L-ikel kien veru tajjeb!</td><td>食物真的好吃！<br><strong>L-ikel</strong>：食物。<br><strong>kien</strong>：当时是。<br><strong>veru</strong>：真的。<br><strong>tajjeb</strong>：好、好吃。</td></tr><tr><td>Waqt li kont qed niekol, ċappast il-libsa biż-zalza u oħti qagħdet tidħak bija għax tgħidli li ma nafx niekol.</td><td>吃饭时把酱弄到裙上，姐妹一直笑我，说我连饭都不会吃。<br><strong>Waqt li</strong>：当……时。<br><strong>kont qed niekol</strong>：我当时正在吃。<br><strong>ċappast</strong>：我弄脏了。<br><strong>il-libsa</strong>：连衣裙。<br><strong>biż-zalza</strong>：用酱／被酱。<br><strong>u oħti</strong>：而我姐妹。<br><strong>qagħdet tidħak bija</strong>：一直笑话我，bija＝对着我。<br><strong>għax tgħidli</strong>：因为她对我说。<br><strong>li ma nafx niekol</strong>：我不会吃饭。</td></tr><tr><td>Wara l-ikel morna mixja mal-irdum u xtrajna ġelat.</td><td>饭后沿悬崖散步，买冰淇淋。<br><strong>Wara l-ikel</strong>：饭后。<br><strong>morna mixja</strong>：我们去散步。<br><strong>mal-irdum</strong>：沿着悬崖。<br><strong>u xtrajna ġelat</strong>：并买了冰淇淋。</td></tr><tr><td>Xi t-tlieta ta’ waranofsinhar soqna għal Ħ’Attard u żorna ftit lin-nanna.</td><td>下午三点左右，开去 Attard，探望奶奶一会儿。<br><strong>Xi t-tlieta</strong>：大约三点，xi 表约数。<br><strong>ta’ waranofsinhar</strong>：下午的。<br><strong>soqna</strong>：我们开车。<br><strong>għal Ħ’Attard</strong>：到 Attard。<br><strong>u żorna ftit</strong>：并探望一会儿。<br><strong>lin-nanna</strong>：奶奶／外婆。</td></tr><tr><td>In-nanna Lina tatna biċċa kejk u qagħdet titkellem ftit magħna.</td><td>奶奶 Lina 给我们蛋糕，聊了一会儿。<br><strong>In-nanna Lina</strong>：奶奶 Lina。<br><strong>tatna</strong>：她给我们，tat + na。<br><strong>biċċa kejk</strong>：一块蛋糕。<br><strong>u qagħdet titkellem ftit</strong>：并聊了一会儿，持续动作。<br><strong>magħna</strong>：与我们。</td></tr><tr><td>Wara morna lura d-dar għax konna għajjenin.</td><td>后来因为累了，我们回家。<br><strong>Wara</strong>：后来。<br><strong>morna lura d-dar</strong>：我们回家。<br><strong>għax</strong>：因为。<br><strong>konna għajjenin</strong>：我们很累，复数。</td></tr><tr><td>Sakemm wasalna d-dar, oħti raqdet fuq spallti waqt li jien qgħadt inħares ’il barra mit-tieqa nosserva t-toroq.</td><td>回家路上，姐妹睡在我肩上，我一直看窗外街道。<br><strong>Sakemm wasalna d-dar</strong>：直到到家这段时间。<br><strong>oħti raqdet</strong>：姐妹睡了。<br><strong>fuq spallti</strong>：在我肩上，spalla 的所属形式。<br><strong>waqt li jien</strong>：而我。<br><strong>qgħadt inħares</strong>：一直看，不必逐字译“坐下”。<br><strong>’il barra mit-tieqa</strong>：向窗外。<br><strong>nosserva t-toroq</strong>：观察街道。</td></tr><tr><td>Rajt ħafna karozzi u nies għaddejjin, però l-iktar ħaġa li laqtitni kienet villa kbira u lussuża.</td><td>看见很多车与行人，但印象最深的是豪华大别墅。<br><strong>Rajt</strong>：我看见。<br><strong>ħafna karozzi</strong>：很多汽车。<br><strong>u nies għaddejjin</strong>：与经过的人。<br><strong>però</strong>：但是。<br><strong>l-iktar ħaġa li laqtitni</strong>：最令我印象深刻的事物。<br><strong>kienet</strong>：是。<br><strong>villa kbira u lussuża</strong>：大而豪华的别墅，阴性。</td></tr><tr><td>Kellha grada kbira kulur id-deheb u ħafna twieqi mal-faċċata.</td><td>别墅有金色大门，正面很多窗。<br><strong>Kellha</strong>：它有，过去时阴性，指 villa。<br><strong>grada kbira</strong>：大门。<br><strong>kulur id-deheb</strong>：金色；不等于纯金制造。<br><strong>u ħafna twieqi</strong>：和很多窗。<br><strong>mal-faċċata</strong>：沿建筑正面。</td></tr><tr><td>Quddiemha kien hemm żewġ karozzi moderni, waħda ħamra u l-oħra bajda.</td><td>别墅前有两辆现代汽车，一红一白。<br><strong>Quddiemha</strong>：它前面，-ha 指别墅。<br><strong>kien hemm</strong>：当时有。<br><strong>żewġ karozzi moderni</strong>：两辆现代汽车，复数。<br><strong>waħda ħamra</strong>：一辆红色，阴性配 karozza。<br><strong>u l-oħra bajda</strong>：另一辆白色。</td></tr></tbody></table><h3 id="叙事顺序" tabindex="-1">叙事顺序 <a class="header-anchor" href="#叙事顺序" aria-label="Permalink to &quot;叙事顺序&quot;">​</a></h3><p>星期天早上出门 → Żurrieq 看海、山谷和 Filfla → Siġġiewi 弥撒 → Dingli 午餐及悬崖步行 → 约下午三点到 Attard 探望 Lina → 回家路上看见别墅。上文没有说自家汽车的颜色，也没有说那幢别墅是 Sara 的家。</p><hr><h2 id="_15-九道阅读问答" tabindex="-1">15 九道阅读问答 <a class="header-anchor" href="#_15-九道阅读问答" aria-label="Permalink to &quot;15 九道阅读问答&quot;">​</a></h2><h3 id="九道阅读问答-完整参考答案" tabindex="-1">九道阅读问答：完整参考答案 <a class="header-anchor" href="#九道阅读问答-完整参考答案" aria-label="Permalink to &quot;九道阅读问答：完整参考答案&quot;">​</a></h3><p><code>A. Wieġeb</code>＝A 部分：回答；<strong>Wieġeb</strong> 是“回答”的命令式。</p><table tabindex="0"><thead><tr><th>题目与回答</th><th>中文与逐词／短语解析</th></tr></thead><tbody><tr><td>1. Meta ħarġet mal-familja tagħha Sara? — Sara ħarġet mal-familja tagħha nhar il-Ħadd li għadda.</td><td>Sara 何时与家人出去？——上个周日。<br><strong>Meta</strong>：何时。<br><strong>ħarġet</strong>：她出去了。<br><strong>mal-familja tagħha</strong>：与她的家人。<br><strong>Sara</strong>：人名。<br><strong>nhar il-Ħadd li għadda</strong>：上个星期天。</td></tr><tr><td>2. Kif kien it-temp dakinhar? — Dakinhar kienet xemx tisreġ u kien hemm ħafna sħana.</td><td>那天天气怎样？——烈日炎炎、很热。<br><strong>Kif kien it-temp</strong>：天气怎样。<br><strong>dakinhar</strong>：那一天。<br><strong>kienet xemx tisreġ</strong>：太阳火辣。<br><strong>u kien hemm</strong>：并有。<br><strong>ħafna sħana</strong>：很大的热度。</td></tr><tr><td>3. X’libset Sara? — Sara libset libsa ħafifa u żanżnet sandli ġdid.</td><td>穿什么？——轻薄裙，初穿新凉鞋。<br><strong>X’libset</strong>：她穿了什么。<br><strong>Sara libset</strong>：Sara 穿了。<br><strong>libsa ħafifa</strong>：轻薄连衣裙。<br><strong>u żanżnet</strong>：并初次穿用，第三人称阴性过去时。<br><strong>sandli ġdid</strong>：新凉鞋，沿用课文。</td></tr><tr><td>4. X’kulur kienet il-qmis ta’ missier Sara? — Il-qmis ta’ missier Sara kienet safra.</td><td>父亲的衬衣什么颜色？——黄色。<br><strong>X’kulur</strong>：什么颜色。<br><strong>kienet</strong>：当时是，阴性。<br><strong>il-qmis</strong>：衬衣。<br><strong>ta’ missier Sara</strong>：Sara 父亲的。<br><strong>safra</strong>：黄色，阴性。</td></tr><tr><td>5. Fi x’ħin telqu mid-dar? — Telqu mid-dar fl-għaxra ta’ filgħodu.</td><td>几点离家？——早上十点。<br><strong>Fi x’ħin</strong>：在几点。<br><strong>telqu</strong>：他们离开。<br><strong>mid-dar</strong>：从家。<br><strong>fl-għaxra</strong>：十点。<br><strong>ta’ filgħodu</strong>：上午的。</td></tr><tr><td>6. Semmi tliet postijiet li marru fihom il-familja ta’ Sara. — Il-familja marret iż-Żurrieq biex tara l-veduta, is-Siġġiewi għall-quddies u Ħad-Dingli għall-ikla ta’ nofsinhar.</td><td>列三处。——Żurrieq 看景、Siġġiewi 弥撒、Dingli 午饭。<br><strong>Semmi</strong>：说出。<br><strong>tliet postijiet</strong>：三个地方。<br><strong>li marru fihom</strong>：他们去过的。<br><strong>il-familja ta’ Sara</strong>：Sara 家庭。<br><strong>Il-familja marret</strong>：家庭去了，集合名词可配单数。<br><strong>iż-Żurrieq</strong>：地名。<br><strong>biex tara l-veduta</strong>：为了看景。<br><strong>is-Siġġiewi għall-quddies</strong>：到 Siġġiewi 参加弥撒。<br><strong>u Ħad-Dingli għall-ikla ta’ nofsinhar</strong>：到 Dingli 午饭。</td></tr><tr><td>7. X’kielet Sara u għaliex bdiet tidħak biha oħtha? — Sara kielet għaġin biż-zalza ħamra. Oħtha bdiet tidħak biha għax ċappset il-libsa biż-zalza.</td><td>吃什么，姐妹为什么笑她？——红酱意面，酱弄脏裙子。<br><strong>X’kielet</strong>：她吃了什么。<br><strong>u għaliex</strong>：而为什么。<br><strong>bdiet tidħak biha</strong>：开始笑她。<br><strong>oħtha</strong>：她的姐妹。<br><strong>għaġin biż-zalza ħamra</strong>：红酱意面。<br><strong>għax ċappset</strong>：因为她弄脏了。<br><strong>il-libsa biż-zalza</strong>：裙子沾酱。</td></tr><tr><td>8. X’jisimha n-nanna ta’ Sara u x’tathom meta marru jarawha? — In-nanna ta’ Sara jisimha Lina u tathom biċċa kejk meta marru jarawha.</td><td>奶奶叫什么，给了什么？——Lina，给了蛋糕。<br><strong>X’jisimha</strong>：她叫什么。<br><strong>n-nanna ta’ Sara</strong>：Sara 的奶奶／外婆。<br><strong>u x’tathom</strong>：并给了他们什么。<br><strong>meta marru jarawha</strong>：他们去看她时。<br><strong>jisimha Lina</strong>：她叫 Lina。<br><strong>u tathom biċċa kejk</strong>：并给他们蛋糕；tat + hom。</td></tr><tr><td>9. Fi kliemek iddeskrivi l-villa li rat Sara u l-karozzi li kien hemm quddiemha. — Sara rat villa kbira u lussuża, bi grada kbira kulur id-deheb u ħafna twieqi fuq il-faċċata. Quddiem il-villa kien hemm żewġ karozzi moderni, waħda ħamra u l-oħra bajda.</td><td>用自己的话描述别墅及门前汽车。——豪华大别墅、金色大门、很多窗；门前两辆现代车，一红一白。<br><strong>Fi kliemek</strong>：用你自己的话。<br><strong>iddeskrivi</strong>：描述。<br><strong>l-villa li rat Sara</strong>：Sara 看到的别墅。<br><strong>u l-karozzi</strong>：与汽车。<br><strong>li kien hemm quddiemha</strong>：当时在它前面的。<br><strong>Sara rat</strong>：Sara 看见了。<br><strong>villa kbira u lussuża</strong>：大而豪华的别墅。<br><strong>bi grada kbira</strong>：有大门。<br><strong>kulur id-deheb</strong>：金色。<br><strong>u ħafna twieqi fuq il-faċċata</strong>：正面很多窗。<br><strong>Quddiem il-villa</strong>：别墅前面。<br><strong>kien hemm żewġ karozzi moderni</strong>：有两辆现代汽车。<br><strong>waħda ħamra u l-oħra bajda</strong>：一红一白。</td></tr></tbody></table><hr><h2 id="_16-十道判断与答案速查" tabindex="-1">16 十道判断与答案速查 <a class="header-anchor" href="#_16-十道判断与答案速查" aria-label="Permalink to &quot;16 十道判断与答案速查&quot;">​</a></h2><h3 id="十道判断-区分错误与未提及" tabindex="-1">十道判断：区分错误与未提及 <a class="header-anchor" href="#十道判断-区分错误与未提及" aria-label="Permalink to &quot;十道判断：区分错误与未提及&quot;">​</a></h3><p><code>B. Wieġeb V jekk veru jew F jekk falz. Meta t-tweġiba tkun falz, irranġaha tajba taħtha</code>＝正确填 V，错误填 F；错误时在下面改正。</p><p><strong>Wieġeb</strong>：回答。<br><strong>V / veru</strong>：真／正确。<br><strong>F / falz</strong>：假／错误。<br><strong>jekk</strong>：如果。<br><strong>jew</strong>：或者。<br><strong>Meta t-tweġiba tkun falz</strong>：答案为假时，沿原文表达。<br><strong>irranġaha tajba</strong>：把它改对。<br><strong>taħtha</strong>：在它下面。</p><p>“F”有时在这份练习中承担“课文不支持”的作用；阅读时必须另标原因，不能把没写的颜色、宠物或住所编出来。</p><table tabindex="0"><thead><tr><th>题目、判断与修正</th><th>中文与逐词／短语解析</th></tr></thead><tbody><tr><td>1. Fil-familja ta’ Sara hemm erba’ persuni. — <strong>V，按本次出游四人的题意。严格说家庭总人数未完全说明。</strong><br>更严谨：F’din il-ħarġa kien hemm Sara, oħtha, ommha u missierha.</td><td>Sara 家有四人。——文章写了四人出游，不证明没有其他家人。<br><strong>Fil-familja ta’ Sara</strong>：在 Sara 家。<br><strong>hemm</strong>：有。<br><strong>erba’ persuni</strong>：四人。<br><strong>F’din il-ħarġa</strong>：这次出游中。<br><strong>kien hemm</strong>：有。<br><strong>Sara, oħtha, ommha u missierha</strong>：Sara、她的姐妹、母亲、父亲。</td></tr><tr><td>2. Oħt Sara libset flokk bil-komma qasira u qalziet aħmar. — <strong>F</strong>。<br>Oħt Sara libset flokk abjad bil-komma qasira u qalziet <strong>blu</strong>.</td><td>姐妹穿短袖、红裤。——错，是白短袖与蓝裤。<br><strong>Oħt Sara</strong>：Sara 的姐妹。<br><strong>libset</strong>：她穿了。<br><strong>flokk bil-komma qasira</strong>：短袖上衣。<br><strong>u qalziet aħmar</strong>：和红裤子。<br><strong>abjad</strong>：白色，补充课文信息。<br><strong>blu</strong>：蓝色，纠正重点。</td></tr><tr><td>3. Omm Sara libset qmis roża u qalziet iswed. — <strong>F</strong>。<br>Omm Sara libset <strong>blaws roża u dublett iswed sal-irkoppa</strong>.</td><td>母亲粉红衬衣、黑裤。——错，是粉红女式衬衫、黑及膝裙。<br><strong>Omm Sara</strong>：Sara 母亲。<br><strong>libset</strong>：她穿了。<br><strong>qmis roża</strong>：粉红衬衣，题目用词。<br><strong>u qalziet iswed</strong>：与黑裤。<br><strong>blaws roża</strong>：粉红女式衬衫，原文。<br><strong>dublett iswed sal-irkoppa</strong>：黑色及膝裙。</td></tr><tr><td>4. Il-karozza tal-papà ta’ Sara hija ħadra. — <strong>未提及；若必须二选一，F＝原文不支持。</strong><br>Is-silta ma tgħidx x’kulur għandha l-karozza tal-papà ta’ Sara.</td><td>父亲的车是绿色。——没有颜色信息，不能改成红／白／黑。<br><strong>Il-karozza</strong>：汽车。<br><strong>tal-papà ta’ Sara</strong>：Sara 爸爸的。<br><strong>hija ħadra</strong>：是绿色。<br><strong>Is-silta ma tgħidx</strong>：文章没有说。<br><strong>x’kulur għandha</strong>：它是什么颜色。<br><strong>l-karozza tal-papà ta’ Sara</strong>：Sara 爸爸的汽车。</td></tr><tr><td>5. Sara għandha kelba jisimha Filfla. — <strong>F，题目混淆岛名；是否养狗未交代。</strong><br>Fis-silta, Filfla hija gżira li raw minn iż-Żurrieq; ma jissemmiex kelb ta’ Sara.</td><td>Sara 有只母狗叫 Filfla。——课文的 Filfla 是岛，不是文中出现的宠物。<br><strong>Sara għandha</strong>：Sara 有。<br><strong>kelba</strong>：母狗。<br><strong>jisimha Filfla</strong>：它叫 Filfla。<br><strong>Fis-silta</strong>：文章里。<br><strong>Filfla hija gżira</strong>：Filfla 是岛。<br><strong>li raw minn iż-Żurrieq</strong>：他们从 Żurrieq 看到的。<br><strong>ma jissemmiex kelb ta’ Sara</strong>：未提到 Sara 的狗；不等于断言她没有狗。</td></tr><tr><td>6. Sara u oħtha kielu għaġin biż-zalza bajda. — <strong>F</strong>。<br>Sara u oħtha kielu għaġin biż-zalza <strong>ħamra</strong>.</td><td>两姐妹吃白酱意面。——错，是红酱。<br><strong>Sara u oħtha</strong>：Sara 和她姐妹。<br><strong>kielu</strong>：她们吃了。<br><strong>għaġin</strong>：意面。<br><strong>biż-zalza bajda</strong>：配白酱。<br><strong>ħamra</strong>：红色，阴性配 zalza。</td></tr><tr><td>7. In-nanna ta’ Sara jisimha Rożi. — <strong>F</strong>。<br>In-nanna ta’ Sara jisimha <strong>Lina</strong>.</td><td>奶奶叫 Rożi。——错，是 Lina。<br><strong>In-nanna ta’ Sara</strong>：Sara 奶奶／外婆。<br><strong>jisimha</strong>：她叫。<br><strong>Rożi / Lina</strong>：两个女性名字。</td></tr><tr><td>8. In-nanna ta’ Sarah toqgħod Ħ’Attard. — <strong>V，按到 Attard 探望奶奶的自然理解。</strong></td><td>奶奶住 Attard。<br><strong>In-nanna ta’ Sarah</strong>：Sarah 的奶奶；题目比全文多一个 h，指同一人物。<br><strong>toqgħod</strong>：她居住。<br><strong>Ħ’Attard</strong>：地名 Attard。<br><strong>依据</strong>：课文写前往 Attard 探望奶奶，这是题目预期推断。</td></tr><tr><td>9. Fit-triq lejn id-dar, Sara raqdet. — <strong>F</strong>。<br>Fit-triq lejn id-dar, <strong>oħt Sara</strong> raqdet fuq spallitha, waqt li Sara qagħdet tħares ’il barra mit-tieqa.</td><td>回家路上 Sara 睡着。——错，是姐妹靠她肩睡，Sara 看窗外。<br><strong>Fit-triq lejn id-dar</strong>：回家途中。<br><strong>Sara raqdet</strong>：Sara 睡了。<br><strong>oħt Sara</strong>：Sara 的姐妹，纠正主语。<br><strong>fuq spallitha</strong>：在她肩上，此处指 Sara 的肩。<br><strong>waqt li Sara</strong>：而 Sara。<br><strong>qagħdet tħares</strong>：一直看。<br><strong>’il barra mit-tieqa</strong>：向窗外。</td></tr><tr><td>10. Sara toqgħod ġo villa kbira u lussuża. — <strong>未证实；按题目意图 F。</strong><br>Sara rat villa kbira u lussuża mit-tieqa tal-karozza; is-silta ma tgħidx li tgħix fiha.</td><td>Sara 住豪华大别墅。——只说她路上看见，没说住进去。<br><strong>Sara toqgħod</strong>：Sara 居住。<br><strong>ġo villa kbira u lussuża</strong>：在豪华大别墅里。<br><strong>Sara rat</strong>：Sara 看见了。<br><strong>mit-tieqa tal-karozza</strong>：从车窗。<br><strong>is-silta ma tgħidx</strong>：文章没有说。<br><strong>li tgħix fiha</strong>：她住在里面。</td></tr></tbody></table><h3 id="答案速查" tabindex="-1">答案速查 <a class="header-anchor" href="#答案速查" aria-label="Permalink to &quot;答案速查&quot;">​</a></h3><p>按练习预期：<strong>1 V；2 F；3 F；4 未提及（强制二选一作 F）；5 F；6 F；7 F；8 V；9 F；10 未证实（按题意作 F）</strong>。第 1、5、8、10 题的推断边界见上表；不要将阅读题的简化判断扩展为原文没写的事实。</p>',130)])])}const k=r(s,[["render",i]]);export{m as __pageData,k as default};
